package com.yourcompany.godhand.goals;

import com.yourcompany.godhand.GodHand;
import com.yourcompany.godhand.util.IEntityDataSaver;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.ai.goal.Goal;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.minecraft.entity.effect.StatusEffectInstance;
import net.minecraft.entity.effect.StatusEffects;
import net.minecraft.nbt.NbtCompound;

import java.util.EnumSet;

/**
 * Ein Ziel für Begleiter, das ihnen passive Buffs basierend auf ihren NBT-Daten verleiht.
 * Dieses Ziel ist immer aktiv und unterbricht andere Ziele nicht.
 */
public class CompanionBuffGoal extends Goal {
    private static final Logger LOGGER = LoggerFactory.getLogger(GodHand.MOD_ID);
    private final LivingEntity companion;

    /**
     * Erstellt ein neues CompanionBuffGoal.
     * @param companion Der Begleiter, der gebufft werden soll.
     */
    public CompanionBuffGoal(LivingEntity companion) {
        this.companion = companion;
        this.setControls(EnumSet.of(Goal.Control.LOOK)); // Doesn't interrupt other goals
    }

    @Override
    public boolean canStart() {
        // This goal should always be active for a companion.
        return true;
    }


    private void applyEffectIfNeeded(net.minecraft.registry.entry.RegistryEntry<net.minecraft.entity.effect.StatusEffect> effect) {
        StatusEffectInstance current = companion.getStatusEffect(effect);
        if (current == null || current.getDuration() <= 20) {
            companion.addStatusEffect(new StatusEffectInstance(effect, 210, 0, false, false, true));
        }
    }

    @Override
    public void tick() {
        try {
            // Verwende persistentData statt writeNbt für bessere Performance und Zuverlässigkeit
            IEntityDataSaver dataSaver = (IEntityDataSaver) companion;
            NbtCompound nbt = dataSaver.getPersistentData();

            if (!nbt.getBoolean("godhand_is_companion")) {
                return; // Not a companion, do nothing.
            }

            // Apply effects based on persistent data
            if (nbt.getBoolean("godhand_effect_regen")) {
                applyEffectIfNeeded(StatusEffects.REGENERATION);
            }
            if (nbt.getBoolean("godhand_effect_strength")) {
                applyEffectIfNeeded(StatusEffects.STRENGTH);
            }
            if (nbt.getBoolean("godhand_effect_speed")) {
                applyEffectIfNeeded(StatusEffects.SPEED);
            }
            if (nbt.getBoolean("godhand_effect_resistance")) {
                applyEffectIfNeeded(StatusEffects.RESISTANCE);
            }
        } catch (Exception e) {
            // Logge Fehler, aber lasse das Goal weiterlaufen
            LOGGER.error("Error in CompanionBuffGoal.tick()", e);
        }
    }

}

package com.yourcompany.godhand.goals;

import com.yourcompany.godhand.CompanionManager;
import com.yourcompany.godhand.GodHand;
import com.yourcompany.godhand.GodHandConfig;
import net.minecraft.entity.LivingEntity;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.minecraft.entity.ai.goal.Goal;
import net.minecraft.entity.mob.PathAwareEntity;
import net.minecraft.entity.player.PlayerEntity;

import java.util.EnumSet;
import java.util.UUID;

/**
 * Ein Ziel zur Zielauswahl (Target Selection), das es einem Begleiter ermöglicht,
 * Entitäten zu fokussieren, die seinen Besitzer angreifen.
 */
public class CompanionDefendOwnerGoal extends Goal {
    private static final Logger LOGGER = LoggerFactory.getLogger(GodHand.MOD_ID);

    private final PathAwareEntity companion;
    private LivingEntity owner;
    private LivingEntity target;
    private final double defendRadius;

    /**
     * Erstellt ein neues CompanionDefendOwnerGoal.
     * @param companion Der Begleiter, der verteidigen soll.
     */
    public CompanionDefendOwnerGoal(PathAwareEntity companion) {
        this.companion = companion;
        this.defendRadius = GodHandConfig.getInstance().companion.defendRadius;
        this.setControls(EnumSet.of(Control.TARGET));
    }

    /**
     * Überprüft, ob ein Angreifer des Besitzers als Ziel ausgewählt werden kann.
     */
    @Override
    public boolean canStart() {
        try {
            UUID ownerUuid = CompanionManager.getOwnerUuid(this.companion);
            if (ownerUuid == null) return false;

            PlayerEntity player = this.companion.getWorld().getPlayerByUuid(ownerUuid);
            if (player == null || player.isSpectator()) return false;

            this.owner = player;
            LivingEntity attacker = player.getAttacker();

            // Prüfe, ob der Angreifer valide ist und im Verteidigungsradius des Besitzers
            if (attacker != null && attacker.isAlive() && !attacker.isRemoved() && !CompanionManager.isCompanion(attacker)) {
                if (player.squaredDistanceTo(attacker) <= this.defendRadius * this.defendRadius) {
                    this.target = attacker;
                    return true;
                }
            }

            return false;
        } catch (Exception e) {
            // Logge Fehler und verhindere, dass das Goal startet
            LOGGER.error("Error in CompanionDefendOwnerGoal.canStart()", e);
            return false;
        }
    }

    /**
     * Setzt das Ziel auf dem Begleiter-Mob, wenn das Goal startet.
     */
    @Override
    public void start() {
        this.companion.setTarget(this.target);
        super.start();
    }

    /**
     * Überprüft, ob das Ziel weiterhin verfolgt werden soll.
     */
    @Override
    public boolean shouldContinue() {
        if (this.target == null || !this.target.isAlive() || this.target.isRemoved()) {
            return false;
        }

        // Bleibe am Ziel, solange es noch in der Nähe des Besitzers ist
        double extendedRadius = this.defendRadius * 1.25;
        return this.owner.squaredDistanceTo(this.target) <= (extendedRadius * extendedRadius);
    }

    /**
     * Beendet die Zielverfolgung.
     */
    @Override
    public void stop() {
        this.target = null;
    }
}

package com.yourcompany.godhand.goals;

import com.yourcompany.godhand.CompanionManager;
import com.yourcompany.godhand.GodHand;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.ai.goal.Goal;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.minecraft.entity.mob.PathAwareEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.world.World;

import java.util.EnumSet;
import java.util.UUID;

/**
 * Ein benutzerdefiniertes Ziel, das es einem Begleiter ermöglicht, seinem Besitzer zu folgen.
 * Dieses Ziel ist generischer als das Standard-FollowOwnerGoal und funktioniert für jede PathAwareEntity.
 */
public class CompanionFollowOwnerGoal extends Goal {
    private static final Logger LOGGER = LoggerFactory.getLogger(GodHand.MOD_ID);

    private final PathAwareEntity companion;
    private LivingEntity owner;
    private final World world;
    private final double speed;
    private final float minDistance;
    private final float maxDistance;
    private int updateCountdownTicks;

    /**
     * Erstellt ein neues CompanionFollowOwnerGoal.
     * @param companion Der Begleiter, der folgen soll.
     * @param speed Die Bewegungsgeschwindigkeit des Begleiters.
     * @param minDistance Der minimale Abstand zum Besitzer, bevor der Begleiter aufhört zu folgen.
     * @param maxDistance Der maximale Abstand zum Besitzer, bevor der Begleiter beginnt zu folgen.
     */
    public CompanionFollowOwnerGoal(PathAwareEntity companion, double speed, float minDistance, float maxDistance) {
        this.companion = companion;
        this.world = companion.getWorld();
        this.speed = speed;
        this.minDistance = minDistance;
        this.maxDistance = maxDistance;
        this.setControls(EnumSet.of(Control.MOVE, Control.LOOK));
    }

    /**
     * Überprüft, ob dieses Ziel ausgeführt werden kann.
     * @return True, wenn das Ziel ausgeführt werden kann, sonst false.
     */
    @Override
    public boolean canStart() {
        try {
            UUID ownerUuid = CompanionManager.getOwnerUuid(this.companion);
            if (ownerUuid == null) {
                return false;
            }
            PlayerEntity player = this.world.getPlayerByUuid(ownerUuid);
            if (player == null || player.isSpectator()) {
                return false;
            }
            // Don't start if we are already closer than the max distance
            if (this.companion.squaredDistanceTo(player) < (double)(this.maxDistance * this.maxDistance)) {
                return false;
            }
            this.owner = player;
            return true;
        } catch (Exception e) {
            // Logge Fehler und verhindere, dass das Goal startet
            LOGGER.error("Error in CompanionFollowOwnerGoal.canStart()", e);
            return false;
        }
    }

    /**
     * Überprüft, ob dieses Ziel weiterhin ausgeführt werden soll.
     * @return True, wenn das Ziel weiterhin ausgeführt werden soll, sonst false.
     */
    @Override
    public boolean shouldContinue() {
        // Continue if navigation is not idle, owner is not a spectator, and we are further than the min distance
        return !this.companion.getNavigation().isIdle() && !this.owner.isSpectator() && this.companion.squaredDistanceTo(this.owner) > (double)(this.minDistance * this.minDistance);
    }

    /**
     * Beginnt die Ausführung des Ziels.
     */
    @Override
    public void start() {
        this.updateCountdownTicks = 0;
        this.companion.getNavigation().startMovingTo(this.owner, this.speed);
    }

    /**
     * Beendet die Ausführung des Ziels.
     */
    @Override
    public void stop() {
        this.owner = null;
        this.companion.getNavigation().stop();
    }

    /**
     * Führt einen Tick der Ziel-Logik aus.
     */
    @Override
    public void tick() {
        try {
            this.companion.getLookControl().lookAt(this.owner, 10.0F, (float)this.companion.getMaxLookPitchChange());
            if (--this.updateCountdownTicks <= 0) {
                this.updateCountdownTicks = this.adjustTickDelay(10);
                this.companion.getNavigation().startMovingTo(this.owner, this.speed);
            }
        } catch (Exception e) {
            // Logge Fehler und stoppe das Goal bei kritischen Fehlern
            LOGGER.error("Error in CompanionFollowOwnerGoal.tick()", e);
            this.stop();
        }
    }

    private int adjustTickDelay(int i) {
        return i;
    }
}

