import net.minecraft.server.world.ServerWorld;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerEntityEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.entity.effect.StatusEffectInstance;
import net.minecraft.entity.effect.StatusEffects;
import net.minecraft.server.network.ServerPlayerEntity;

import java.util.UUID;
import java.util.List;
import java.util.stream.Collectors;

import com.yourcompany.godhand.util.IEntityDataSaver;
import net.minecraft.entity.projectile.ArrowEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.item.Items;

import com.yourcompany.godhand.item.ModItems;
import net.minecraft.entity.mob.HostileEntity;
import net.minecraft.util.math.Box;

import java.util.concurrent.CompletableFuture;


import static net.minecraft.server.command.CommandManager.argument;
import static net.minecraft.server.command.CommandManager.literal;

/**
 * Die Hauptklasse der GodHand Mod, die die Initialisierung, Befehlsregistrierung und Ereignisbehandlung übernimmt.
 */
public class GodHand implements ModInitializer {
    /**
     * Default constructor for GodHand.
     */
    public GodHand() {
        super();
    }

	/** Die Mod-ID der GodHand Mod. */
	public static final String MOD_ID = "godhand";
	/** Der Logger für die GodHand Mod. */
	public static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);
	/** Gibt an, ob die Mod erfolgreich initialisiert wurde. */
	public static boolean isInitializedSuccessfully = false;
	/** Der Identifier für das Teleport-Begleiter-Paket. */
	public static final Identifier TELEPORT_COMPANION_PACKET_ID = Identifier.of(MOD_ID, "teleport_companion");
    /** Der Identifier für das Freigabe-Begleiter-Paket. */
    public static final Identifier RELEASE_COMPANION_PACKET_ID = Identifier.of(MOD_ID, "release_companion");
    /** Identifier für das Paket zur Abfrage des Begleiterstatus vom Client zum Server. */
    public static final Identifier C2S_REQUEST_COMPANION_STATUS_PACKET_ID = Identifier.of(MOD_ID, "request_companion_status");
    /** Identifier für das Paket zur Antwort auf den Begleiterstatus vom Server zum Client. */
    public static final Identifier S2C_COMPANION_STATUS_RESPONSE_PACKET_ID = Identifier.of(MOD_ID, "response_companion_status");

	/**
	 * Wird beim Initialisieren der Mod aufgerufen. Registriert Ereignisse, Befehle und Netzwerk-Receiver.
	 */
	@Override
	public void onInitialize() {
		LOGGER.info("Hello Fabric world!");
		// Setzt den globalen UncaughtExceptionHandler
		Thread.setDefaultUncaughtExceptionHandler((thread, e) -> {
			GodHand.LOGGER.error("Uncaught exception in thread " + thread.getName(), e);
		});

		try {
			// Lade Konfiguration zuerst

			ModItems.registerModItems();

			// Registriere Lifecycle-Ereignisse für Begleiter-Tracking
			ServerEntityEvents.ENTITY_LOAD.register((entity, world) -> {
				if (entity instanceof LivingEntity livingEntity) {
					CompanionManager.registerCompanion(livingEntity);
				} else if (entity instanceof ArrowEntity arrow) {
					ArrowManager.onArrowLoad(arrow, world);
				} else if (entity instanceof net.minecraft.entity.ItemEntity itemEntity) {
                    net.minecraft.item.ItemStack stack = itemEntity.getStack();
                    if (stack.isOf(net.minecraft.item.Items.BOW) && stack.contains(net.minecraft.component.DataComponentTypes.CUSTOM_NAME)) {
                        String name = stack.getName().getString();
                        if (name.equals("God Hand Bow") || name.equals("Magic Bow")) {
                            // Find nearest player as fallback if we can't directly get thrower
                            java.util.List<net.minecraft.entity.player.PlayerEntity> players = world.getEntitiesByClass(
                                net.minecraft.entity.player.PlayerEntity.class,
                                itemEntity.getBoundingBox().expand(10.0),
                                net.minecraft.entity.Entity::isAlive
                            );

                            if (!players.isEmpty()) {
                                net.minecraft.entity.player.PlayerEntity player = players.get(0);
                                if (player.getInventory().insertStack(stack)) {
                                    itemEntity.discard();
                                }
                            }
                        }
                    }
                }
			});

			ServerEntityEvents.ENTITY_UNLOAD.register((entity, world) -> {
				if (entity instanceof LivingEntity livingEntity) {
					CompanionManager.unregisterCompanion(livingEntity);
				} else if (entity instanceof ArrowEntity arrow) {
					ArrowManager.unregisterArrow(arrow);
				}
			});

			GodHandConfig config = GodHandConfig.getInstance();
			if (config == null) {
				throw new RuntimeException("Failed to load GodHand configuration");
			}

			// Registriere Keybinds

            if (net.fabricmc.loader.api.FabricLoader.getInstance().getEnvironmentType() == net.fabricmc.api.EnvType.CLIENT) {
				GodHandKeybinds.register();
			}


			// Registriere Schadensereignisse
			ServerLivingEntityEvents.ALLOW_DAMAGE.register((entity, source, amount) -> {
				try {
					return GodHandFeatures.handleDamage(entity, source, amount);
				} catch (Exception e) {
					LOGGER.error("Error handling damage event", e);
					return true; // Standard: Schaden zulassen bei Fehler
				}
			});

			// Registriere Todesereignisse
			ServerLivingEntityEvents.AFTER_DEATH.register((entity, source) -> {
				try {
					// Companion Death Message
					if (entity instanceof LivingEntity && CompanionManager.isCompanion(entity)) {
						UUID ownerUuid = CompanionManager.getOwnerUuid(entity);
						if (ownerUuid != null && entity.getServer() != null) {
							ServerPlayerEntity owner = entity.getServer().getPlayerManager().getPlayer(ownerUuid);
							if (owner != null) {
								owner.sendMessage(Text.translatable("godhand.chat.companion.died", entity.getName()), false);
							}
						}
					}

					// Super Bow Kill Message
					if (source.getSource() instanceof ArrowEntity arrow) {
						if (((IEntityDataSaver)arrow).getPersistentData().getBoolean("godhand_super_bow_arrow")) {
							if (arrow.getOwner() instanceof ServerPlayerEntity player) {
								player.sendMessage(Text.translatable("godhand.chat.superbow.kill", entity.getName()), false);
							}
						}
					}
				} catch (Exception e) {
					LOGGER.error("Error handling death event", e);
				}
			});

			// Registriere Server-Befehle
			CommandRegistrationCallback.EVENT.register(this::registerCommands);



			// Registriere Server-Tick-Ereignisse
			ServerTickEvents.END_SERVER_TICK.register(server -> {
				// Optimization: Rate-limit expensive sneak-glow logic to every 10 ticks (approx. 2 times per second)
				if (server.getTicks() % 10 == 0) {
					for (net.minecraft.server.network.ServerPlayerEntity player : server.getPlayerManager().getPlayerList()) {
						// Optimized: Check for items and reduced search radius
						if (player.isSneaking()) {
							ItemStack mainStack = player.getMainHandStack();
							ItemStack offStack = player.getOffHandStack();
							boolean isMatch = false;

							// Check for Magic Bow item or renamed standard bows
							if (mainStack.isOf(ModItems.MAGIC_BOW) || offStack.isOf(ModItems.MAGIC_BOW)) {
								isMatch = true;
							} else if (mainStack.isOf(Items.BOW) || offStack.isOf(Items.BOW)) {
								if (mainStack.contains(net.minecraft.component.DataComponentTypes.CUSTOM_NAME)) {
									String name = mainStack.getName().getString();
									if (name.equals("God Hand Bow") || name.equals("Magic Bow")) isMatch = true;
								}
								if (!isMatch && offStack.contains(net.minecraft.component.DataComponentTypes.CUSTOM_NAME)) {
									String name = offStack.getName().getString();
									if (name.equals("God Hand Bow") || name.equals("Magic Bow")) isMatch = true;
								}
							}

							if (isMatch) {
								// Reduced search radius from 50.0 to 20.0 for better performance (15.6x smaller volume)
								java.util.List<net.minecraft.entity.LivingEntity> entities = player.getWorld().getEntitiesByClass(
									net.minecraft.entity.LivingEntity.class,
									player.getBoundingBox().expand(20.0),
									e -> e != player
								);
								for (net.minecraft.entity.LivingEntity entity : entities) {
									entity.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(net.minecraft.entity.effect.StatusEffects.GLOWING, 15, 0, false, false));
								}
							}
						}
					}
				}

				try {
					for (ServerWorld world : server.getWorlds()) {
						PlayerFeatures.handleSuperBow(world);
					}

					// Effiziente Anwendung von Begleiter-Effekten mit dem neuen Tracking-System
					List<LivingEntity> allActiveCompanions = List.copyOf(CompanionManager.getActiveCompanions());

					// Parallele Verarbeitung der Begleiter-Effekte für bessere Performance
					CompletableFuture.runAsync(() -> {
						GodHandConfig.CompanionConfig companionConfig = config.companion;
						for (LivingEntity companion : allActiveCompanions) {
							if (companion.isAlive()) {
								server.execute(() -> {
									if (companionConfig.giveRegenerationEffect) {
										companion.addStatusEffect(new StatusEffectInstance(StatusEffects.REGENERATION, 20 * 5, 1, false, false));
									}
									if (companionConfig.giveStrengthEffect) {
										companion.addStatusEffect(new StatusEffectInstance(StatusEffects.STRENGTH, 20 * 5, 1, false, false));
									}
									if (companionConfig.giveSpeedEffect) {
										companion.addStatusEffect(new StatusEffectInstance(StatusEffects.SPEED, 20 * 5, 1, false, false));
									}
									if (companionConfig.giveResistanceEffect) {
										companion.addStatusEffect(new StatusEffectInstance(StatusEffects.RESISTANCE, 20 * 5, 1, false, false));
									}
								});
							}
						}
					}).exceptionally(throwable -> {
						LOGGER.error("Error applying companion effects asynchronously", throwable);
						return null;
					});
				} catch (Exception e) {
					LOGGER.error("Error in server tick event", e);
				}
			});

			// Registriere Netzwerk-Receiver
			registerServerReceivers();

        PayloadTypeRegistry.playC2S().register(UpdateBowWhitelistPacket.ID, UpdateBowWhitelistPacket.CODEC);
        PayloadTypeRegistry.playC2S().register(OpenBowWhitelistScreenPacket.ID, OpenBowWhitelistScreenPacket.CODEC);
        PayloadTypeRegistry.playC2S().register(ToggleMagicBowPacket.ID, ToggleMagicBowPacket.CODEC);
        PayloadTypeRegistry.playS2C().register(S2COpenBowWhitelistScreenPacket.ID, S2COpenBowWhitelistScreenPacket.CODEC);
        PayloadTypeRegistry.playS2C().register(SyncBowWhitelistPacket.ID, SyncBowWhitelistPacket.CODEC);


			isInitializedSuccessfully = true;
			LOGGER.info("GodHand Mod initialized successfully!");
		} catch (Exception e) {
			isInitializedSuccessfully = false;
			LOGGER.error("Failed to initialize GodHand Mod!", e);
		}
	}

	/**
	 * Registriert die Server-Netzwerk-Receiver für die Mod.
	 */
	
    private void registerServerReceivers() {
        ServerPlayNetworking.registerGlobalReceiver(UpdateBowWhitelistPacket.ID, (payload, context) -> {
            context.server().execute(() -> {
                if (!context.player().hasPermissionLevel(2)) {
                    LOGGER.warn("Player {} tried to modify Bow Whitelist without permission!", context.player().getName().getString());
                    return;
                }
                BowWhitelistManager.updatePlayerWhitelist(context.server(), payload.input(), payload.add());
            });
        });

        ServerPlayNetworking.registerGlobalReceiver(OpenBowWhitelistScreenPacket.ID, (payload, context) -> {
            context.server().execute(() -> {
                if (context.player().hasPermissionLevel(2)) {
                    ServerPlayNetworking.send(context.player(), new S2COpenBowWhitelistScreenPacket());
                }
            });
        });

        ServerPlayNetworking.registerGlobalReceiver(ToggleMagicBowPacket.ID, (payload, context) -> {
            context.server().execute(() -> {
                if (context.player().hasPermissionLevel(2)) {
                    if (context.player() instanceof com.yourcompany.godhand.util.IEntityDataSaver saver) { boolean current = saver.getPersistentData().getBoolean("magicBowEnabled"); saver.getPersistentData().putBoolean("magicBowEnabled", !current); }
                }
            });
        });
    }

	/**
	 * Registriert die Server-Befehle für die Mod.
	 * @param dispatcher Der CommandDispatcher.
	 * @param registryAccess Der CommandRegistryAccess.
	 * @param environment Die Registrierungsumgebung.
	 */
    public void registerCommands(CommandDispatcher<ServerCommandSource> dispatcher, CommandRegistryAccess registryAccess, CommandManager.RegistrationEnvironment environment) {
		dispatcher.register(literal("godhand")
				.requires(source -> source.hasPermissionLevel(2))
				.then(literal("godmode")
						.then(literal("on").executes(context -> setGodMode(context.getSource(), true)))
						.then(literal("off").executes(context -> setGodMode(context.getSource(), false)))
						.then(literal("toggle").executes(context -> toggleGodMode(context.getSource())))
						.then(literal("c").executes(context -> setCreativeMode(context.getSource())))
				)
				.then(literal("companion")
						.then(literal("recruit")
								.then(argument("entity", EntityArgumentType.entity())
										.executes(context -> recruitCompanionCommand(context))))
						.then(literal("recruit_nearest").executes(context -> recruitNearestCompanionCommand(context.getSource())))
						.then(literal("release")
								.then(argument("entity", EntityArgumentType.entity())
										.executes(context -> releaseCompanionCommand(context))))
						.then(literal("release_all").executes(context -> releaseAllCompanionsCommand(context.getSource())))
						.then(literal("teleport")
								.then(argument("entity", EntityArgumentType.entity())
										.executes(context -> teleportCompanionCommand(context))))
				)
				.then(literal("player")
						.then(literal("superbow").executes(context -> toggleSuperBowCommand(context.getSource())))
						.then(literal("invulnerable").executes(context -> toggleInvulnerableCommand(context.getSource())))
				)
						          .then(literal("bowwhitelist")
										  .requires(source -> source.hasPermissionLevel(2))
										  .executes(context -> {
						              // This command is handled client-side and sends a packet to the server.
						              // The server then opens the screen on the client.
						              // This is a bit of a workaround to get the server instance on the client.
						              return 0;
						          }))
		);
	}

	/**
	 * Setzt den God Mode Status für den Spieler.
	 * @param source Die Befehlsquelle.
	 * @param enable True, um den God Mode zu aktivieren, false zum Deaktivieren.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war, sonst 0.
	 */
	private int setGodMode(ServerCommandSource source, boolean enable) {
		if (GodHandConfig.getInstance().godMode.godModeSettingsLocked) {
			source.sendError(Text.translatable("godhand.chat.godmode.settings_are_locked"));
			return 0;
		}
		GodHandConfig.getInstance().godMode.enabled = enable;
		GodHandConfig.saveAsync(GodHandConfig.getInstance());
		if (source.getPlayer() != null) {
			source.getPlayer().sendMessage(Text.translatable("text.godhand.chat.godmode.toggled", enable ? Text.translatable("options.on") : Text.translatable("options.off")), false);
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Führt den Befehl zum Rekrutieren eines Begleiters aus.
	 * @param context Der Befehlskontext.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
	 */
	private int recruitCompanionCommand(CommandContext<ServerCommandSource> context) {
		try {
			LivingEntity targetEntity = (LivingEntity) EntityArgumentType.getEntity(context, "entity");
			if (targetEntity instanceof PathAwareEntity pathAwareEntity) {
				CompanionManager.recruitCompanion(context.getSource().getPlayer(), pathAwareEntity);
			} else {
				context.getSource().sendError(Text.translatable("godhand.command.companion.not_recruitable"));
			}
		} catch (Exception e) {
			context.getSource().sendError(Text.translatable("godhand.command.companion.recruit_failed"));
			GodHand.LOGGER.error("Failed to recruit companion: ", e);
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Führt den Befehl zum Freigeben eines Begleiters aus.
	 * @param context Der Befehlskontext.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
	 */
	private int releaseCompanionCommand(CommandContext<ServerCommandSource> context) {
		try {
			LivingEntity targetEntity = (LivingEntity) EntityArgumentType.getEntity(context, "entity");
			if (targetEntity instanceof PathAwareEntity pathAwareEntity) {
				CompanionManager.releaseCompanion(context.getSource().getPlayer(), pathAwareEntity);
			} else {
				context.getSource().sendError(Text.translatable("godhand.command.companion.not_a_companion"));
			}
		} catch (Exception e) {
			context.getSource().sendError(Text.translatable("godhand.command.companion.release_failed"));
			GodHand.LOGGER.error("Failed to release companion: ", e);
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Schaltet den God Mode Status für den Spieler um.
	 * @param source Die Befehlsquelle.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war, sonst 0.
	 */
	private int toggleGodMode(ServerCommandSource source) {
		if (GodHandConfig.getInstance().godMode.godModeSettingsLocked) {
			source.sendError(Text.translatable("godhand.chat.godmode.settings_are_locked"));
			return 0;
		}
		boolean newStatus = !GodHandConfig.getInstance().godMode.enabled;
		GodHandConfig.getInstance().godMode.enabled = newStatus;
		GodHandConfig.saveAsync(GodHandConfig.getInstance());
		if (source.getPlayer() != null) {
			source.getPlayer().sendMessage(Text.translatable("text.godhand.chat.godmode.toggled", newStatus ? Text.translatable("options.on") : Text.translatable("options.off")), false);
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Versetzt den Spieler in den Kreativmodus, wenn God Mode aktiviert ist.
	 * @param source Die Befehlsquelle.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war, sonst 0.
	 */
	private int setCreativeMode(ServerCommandSource source) {
		if (source.getPlayer() != null) {
			if (GodHandConfig.getInstance().godMode.enabled) {
				source.getPlayer().changeGameMode(net.minecraft.world.GameMode.CREATIVE);
				source.getPlayer().sendMessage(Text.translatable("godhand.chat.gamemode.creative"), false);
			} else {
				source.sendError(Text.translatable("godhand.chat.gamemode.creative_failed_godmode_off"));
			}
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Führt den Befehl zum Rekrutieren des nächsten Begleiters aus.
	 * @param source Die Befehlsquelle.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
	 */
	private int recruitNearestCompanionCommand(ServerCommandSource source) {
		if (source.getPlayer() != null) {
			CompanionManager.recruitNearestCompanion(source.getPlayer());
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Führt den Befehl zum Freigeben aller Begleiter aus.
	 * @param source Die Befehlsquelle.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
	 */
	private int releaseAllCompanionsCommand(ServerCommandSource source) {
		if (source.getPlayer() != null) {
			CompanionManager.releaseAllCompanions(source.getPlayer());
		}
		return Command.SINGLE_SUCCESS;
	}

	/**
	 * Führt den Befehl zum Teleportieren eines Begleiters aus.
	 * @param context Der Befehlskontext.
	 * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
	 */
	private int teleportCompanionCommand(CommandContext<ServerCommandSource> context) {
		try {
			LivingEntity targetEntity = (LivingEntity) EntityArgumentType.getEntity(context, "entity");
			if (targetEntity instanceof PathAwareEntity pathAwareEntity) {
				CompanionManager.teleportCompanion(context.getSource().getPlayer(), pathAwareEntity);
			} else {
				context.getSource().sendError(Text.translatable("godhand.command.companion.not_a_companion"));
			}
		} catch (Exception e) {
			context.getSource().sendError(Text.translatable("godhand.command.companion.teleport_failed"));
			GodHand.LOGGER.error("Failed to teleport companion: ", e);
		}
		return Command.SINGLE_SUCCESS;
	}    /**
     * Schaltet den Super-Bogen Status für den Spieler um.
     * @param source Die Befehlsquelle.
     * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
     */
    private int toggleSuperBowCommand(ServerCommandSource source) {
        GodHandConfig.getInstance().player.superBowEnabled = !GodHandConfig.getInstance().player.superBowEnabled;
        GodHandConfig.saveAsync(GodHandConfig.getInstance());
        if (source.getPlayer() != null) {
            ServerPlayerEntity player = source.getPlayer();
            boolean enabled = GodHandConfig.getInstance().player.superBowEnabled;

            if (enabled) {
                // Add bow and arrows
                player.getInventory().insertStack(new ItemStack(Items.BOW));
                player.getInventory().insertStack(new ItemStack(Items.ARROW, 64));
                player.sendMessage(Text.translatable("godhand.chat.superbow.enabled"), false);
            } else {
                // Remove bow and arrows
                for (int i = 0; i < player.getInventory().size(); i++) {
                    ItemStack stack = player.getInventory().getStack(i);
                    if (stack.getItem() == Items.BOW || stack.getItem() == Items.ARROW) {
                        player.getInventory().removeStack(i);
                    }
                }
                player.sendMessage(Text.translatable("godhand.chat.superbow.disabled"), false);
            }
            source.getPlayer().sendMessage(Text.translatable("godhand.chat.player.super_bow_updated", enabled ? Text.translatable("options.on") : Text.translatable("options.off")), false);
        }
        return Command.SINGLE_SUCCESS;
    }

    /**
     * Schaltet den Unverwundbarkeitsstatus für den Spieler um.
     * @param source Die Befehlsquelle.
     * @return Command.SINGLE_SUCCESS, wenn der Befehl erfolgreich war.
     */
    private int toggleInvulnerableCommand(ServerCommandSource source) {
        if (source.getPlayer() != null) {
            source.getPlayer().setInvulnerable(!source.getPlayer().isInvulnerable());
            source.getPlayer().sendMessage(Text.translatable("godhand.chat.player.invulnerable_updated", source.getPlayer().isInvulnerable() ? Text.translatable("options.on") : Text.translatable("options.off")), false);
        }
        return Command.SINGLE_SUCCESS;
    }
}

package com.yourcompany.godhand;
import com.yourcompany.godhand.network.*;


import com.yourcompany.godhand.gui.SimpleCompanionScreen;
import net.fabricmc.api.ClientModInitializer;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;
import com.yourcompany.godhand.gui.BowWhitelistScreen;
import net.minecraft.client.MinecraftClient;
import net.minecraft.entity.player.PlayerEntity;


/**
 * Client-seitige Initialisierung der GodHand Mod.
 */
public class GodHandClient implements ClientModInitializer {
    /**
     * Opens the crash screen.
     * @param e the throwable causing the crash
     */
    public static void showCrashScreen(Throwable e) {
        if (net.minecraft.client.MinecraftClient.getInstance() != null) {
            net.minecraft.client.MinecraftClient.getInstance().execute(() -> {
                net.minecraft.client.MinecraftClient.getInstance().setScreen(new com.yourcompany.godhand.gui.GodHandCrashScreen(e));
            });
        }
    }

    /**
     * Opens a simple informational screen.
     */
    public static void showSimpleScreen() {
        if (net.minecraft.client.MinecraftClient.getInstance() != null) {
            net.minecraft.client.MinecraftClient.getInstance().execute(() -> {
                net.minecraft.client.MinecraftClient.getInstance().setScreen(new com.yourcompany.godhand.gui.SimpleGodHandScreen());
            });
        }
    }

    /**
     * Default constructor for GodHandClient.
     */
    public GodHandClient() {
        super();
    }


    /**
     * Wird beim Initialisieren der Client-Mod aufgerufen. Hier können client-spezifische Logiken, wie z.B. Rendering, eingerichtet werden.
     */
    @Override
    public void onInitializeClient() {
        registerClientReceivers();
        // This entrypoint is suitable for setting up client-specific logic, such as rendering.

        ClientTickEvents.END_CLIENT_TICK.register(client -> {
            PlayerEntity player = client.player;
            if (player != null) {
                // Apply God Mode effects continuously if enabled
                if (GodHandConfig.getInstance().godMode.enabled || GodHandConfig.getInstance().godMode.smartModeEnabled) {
                    GodHandFeatures.applyGodModeEffects(player);
                }

                // Continuous logging if diagnostic mode is enabled
                if (GodHandConfig.getInstance().godMode.diagnosticModeEnabled) {
                    GodHandConfig.GodModeConfig godModeConfig = GodHandConfig.getInstance().godMode;
                    DiagnosticManager.log(
                            "[Continuous Diagnostic] God Mode: " + godModeConfig.enabled +
                            ", Health: " + player.getHealth() + "/" + player.getMaxHealth() +
                            ", Hunger: " + player.getHungerManager().getFoodLevel() +
                            ", Smart Mode: " + godModeConfig.smartModeEnabled +
                            ", Allow Flying: " + player.getAbilities().allowFlying
                    );
                }

            }
        });

        // Apply God Hand settings when the player joins the world
        ClientPlayConnectionEvents.JOIN.register((handler, sender, client) -> {
            PlayerEntity player = client.player;
            if (player != null) {
                GodHandConfig.GodModeConfig godModeConfig = GodHandConfig.getInstance().godMode;
                if (godModeConfig.enabled || godModeConfig.smartModeEnabled) {
                    GodHandFeatures.applyGodModeEffects(player);
                    DiagnosticManager.log("God Hand settings applied on world join: God Mode=" + godModeConfig.enabled + ", Smart Mode=" + godModeConfig.smartModeEnabled);
                } else {
                    DiagnosticManager.log("God Hand settings not applied on world join: God Mode and Smart Mode are disabled.");
                }
            } else {
                DiagnosticManager.log("God Hand settings could not be applied on world join: Player is null.");
            }
        });
    }

    /**
     * Öffnet den SimpleCompanionScreen.
     */
    public static void openCompanionScreen() {
        MinecraftClient.getInstance().setScreen(new SimpleCompanionScreen(null));
    }

    /**
     * Registriert die Client-Netzwerk-Receiver für die Mod.
     */
    
    private void registerClientReceivers() {
        ClientPlayNetworking.registerGlobalReceiver(S2COpenBowWhitelistScreenPacket.ID, (payload, context) -> {
            context.client().execute(() -> {
                context.client().setScreen(new BowWhitelistScreen(context.client().currentScreen));
            });
        });

        ClientPlayNetworking.registerGlobalReceiver(SyncBowWhitelistPacket.ID, (payload, context) -> {
            context.client().execute(() -> {
                com.yourcompany.godhand.BowWhitelistManager.updateLocalWhitelist(payload.whitelist());
            });
        });
    }

}

package com.yourcompany.godhand;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import net.fabricmc.loader.api.FabricLoader;

import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Path;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Repräsentiert die Konfiguration der GodHand Mod.
 * Lädt und speichert die Konfiguration aus einer JSON-Datei.
 */
public class GodHandConfig {
    /**
     * Default constructor for GodHandConfig.
     */
    public GodHandConfig() {
        super();
    }


    /** Der Gson-Objekt für die Serialisierung und Deserialisierung der Konfiguration. */
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();
    /** Der Pfad zur Konfigurationsdatei. */
    private static final Path CONFIG_PATH = getConfigPath();

    private static Path getConfigPath() {
        try {
            return FabricLoader.getInstance().getConfigDir().resolve("godhand.json");
        } catch (Exception | Error e) {
            // Fallback für Tests, wenn FabricLoader nicht initialisiert ist
            return Path.of("godhand.json");
        }
    }

    /** Konfiguration für den God Mode. */
    public GodModeConfig godMode = new GodModeConfig();

    /**
     * Konfigurationseinstellungen für den God Mode.
     */
    public static class GodModeConfig {
    /**
     * Default constructor for GodModeConfig.
     */
    public GodModeConfig() {
        super();
    }

        /** Gibt an, ob der God Mode aktiviert ist. */
        public boolean enabled = false;
        /** Gibt an, ob die Unverwundbarkeit nach dem Respawn aktiviert ist. */
        public boolean respawnInvulnerability = true;
        /** Gibt an, ob Explosionen blockiert werden sollen. */
        public boolean blockExplosions = true;
        /** Gibt an, ob Feuerschaden blockiert werden soll. */
        public boolean blockFire = true;
        /** Gibt an, ob der Flugmodus aktiviert ist. */
        public boolean flightEnabled = false;
        /** Gibt an, ob die God Mode Einstellungen gesperrt sind. */
        public boolean godModeSettingsLocked = false;
        /** Gibt an, ob der Smart Mode aktiviert ist. */
        public boolean smartModeEnabled = false;
        /** Gibt an, ob der Diagnostic Mode aktiviert ist. */
        public boolean diagnosticModeEnabled = false;
    }

    /** Konfiguration für Begleiter. */
    public CompanionConfig companion = new CompanionConfig();

    /** Konfiguration für Spieler-Features. */
    public PlayerConfig player = new PlayerConfig();

    /**
     * Konfigurationseinstellungen für Begleiter.
     */
    public static class CompanionConfig {
    /**
     * Default constructor for CompanionConfig.
     */
    public CompanionConfig() {
        super();
    }

        /** Die maximale Anzahl an Begleitern, die ein Spieler haben kann. */
        public int maxCompanions = 1;
        /** Die Distanz, in der Begleiter dem Spieler folgen. */
        public double followDistance = 3.0;
        /** Der Radius, in dem Begleiter den Spieler verteidigen. */
        public double defendRadius = 10.0;
        /** Der Radius, in dem Begleiter rekrutiert werden können. */
        public double recruitRadius = 10.0;
        /** Gibt an, ob Begleiter zusätzliche Gesundheit erhalten sollen. */
        public boolean giveExtraHealth = true;
        /** Die Menge an zusätzlicher Gesundheit, die Begleiter erhalten. */
        public int extraHealthAmount = 100;
        /** Gibt an, ob Begleiter den Regenerationseffekt erhalten sollen. */
        public boolean giveRegenerationEffect = false;
        /** Gibt an, ob Begleiter den Stärkeeffekt erhalten sollen. */
        public boolean giveStrengthEffect = false;
        /** Gibt an, ob Begleiter den Geschwindigkeitseffekt erhalten sollen. */
        public boolean giveSpeedEffect = false;
        /** Gibt an, ob Begleiter den Widerstandseffekt erhalten sollen. */
        public boolean giveResistanceEffect = false;
    }

    /**
     * Konfigurationseinstellungen für Spieler-Features.
     */
    public static class PlayerConfig {
    /**
     * Default constructor for PlayerConfig.
     */
    public PlayerConfig() {
        super();
    }

        /** Gibt an, ob der Super-Bogen aktiviert ist. */
        public boolean superBowEnabled = false;
        /** Gibt an, ob der Magische Bogen aktiviert ist. */
        public boolean magicBowEnabled = false;
        /** Gibt an, ob die Pfeil-Duplizierung aktiviert ist. */
        public boolean arrowDuplicationEnabled = false;
        /** Die Anzahl der duplizierten Pfeile. */
        public int arrowDuplicationAmount = 5;
        /** Der Radius, in dem Pfeile nach Feinden suchen. */
        public double arrowSeekRadius = 20.0;
        /** Gibt an, ob der Super-Bogen alle Mobs angreift. */
        public boolean superBowTargetsAllMobs = false;
        /** Konfigurationseinstellungen für den Explosionsbogen. */
        public ExplosiveBowConfig explosiveBowConfig = new ExplosiveBowConfig();
        /** Konfigurationseinstellungen für die Bogen-Whitelist. */
        public BowWhitelistConfig bowWhitelistConfig = new BowWhitelistConfig();
    }

    /**
     * Konfigurationseinstellungen für die Bogen-Whitelist.
     */
    public static class BowWhitelistConfig {
    /**
     * Default constructor for BowWhitelistConfig.
     */
    public BowWhitelistConfig() {
        super();
    }

        /** Ein Set von UUIDs der Spieler, die Bogen-Funktionen nutzen dürfen. */
        public Set<String> whitelistedPlayers = ConcurrentHashMap.newKeySet();
    }

    /**
     * Konfigurationseinstellungen für den Explosionsbogen.
     */
    public static class ExplosiveBowConfig {
    /**
     * Default constructor for ExplosiveBowConfig.
     */
    public ExplosiveBowConfig() {
        super();
    }

        /** Gibt an, ob der Explosionsbogen aktiviert ist. */
        public boolean enabled = false;
        /** Der Radius der Explosion. */
        public double explosionRadius = 3.0; // Default radius
        /** Der Modus der Explosion (0 für nur Schaden, 1 für Schaden + Blockzerstörung). */
        public int explosionMode = 0; // 0 for damage only, 1 for damage + block destruction
    }

    private static GodHandConfig INSTANCE;
    /** Executor für asynchrone Speichervorgänge, um den Hauptthread nicht zu blockieren. */
    private static final ExecutorService SAVE_EXECUTOR = Executors.newSingleThreadExecutor(r -> {
        Thread thread = new Thread(r, "GodHand-Config-Save-Thread");
        thread.setDaemon(true);
        return thread;
    });

    /**
     * Gibt die Singleton-Instanz der GodHandConfig zurück.
     * Lädt die Konfiguration, falls sie noch nicht geladen wurde.
     * @return Die Singleton-Instanz der GodHandConfig.
     */
    public static synchronized GodHandConfig getInstance() {
        if (INSTANCE == null) {
            INSTANCE = load();
        }
        return INSTANCE;
    }

    /**
     * Lädt die Konfiguration aus der Konfigurationsdatei.
     * Wenn die Datei nicht existiert oder ungültig ist, wird eine neue Konfiguration erstellt und gespeichert.
     * @return Die geladene oder neu erstellte GodHandConfig-Instanz.
     */
    private static GodHandConfig load() {
        try (FileReader reader = new FileReader(CONFIG_PATH.toFile())) {
            INSTANCE = GSON.fromJson(reader, GodHandConfig.class);
            if (INSTANCE == null) {
                INSTANCE = new GodHandConfig();
            }
            // Validiere und korrigiere die geladene Konfiguration
            validateAndCorrectConfig(INSTANCE);
        } catch (IOException e) {
            GodHand.LOGGER.warn("Failed to load config, creating new one.", e);
            INSTANCE = new GodHandConfig();
        } catch (Exception e) {
            GodHand.LOGGER.error("Error parsing config file, creating new one.", e);
            INSTANCE = new GodHandConfig();
        }
        save(INSTANCE); // Save to ensure default values are written if file was missing or invalid
        return INSTANCE;
    }

    /**
     * Validiert und korrigiert die Konfigurationswerte.
     * @param config Die zu validierende Konfiguration.
     */
    static void validateAndCorrectConfig(GodHandConfig config) {
        if (config == null) return;

        // Sicherstellen, dass die Konfigurationsabschnitte nicht null sind
        if (config.godMode == null) config.godMode = new GodModeConfig();
        if (config.companion == null) config.companion = new CompanionConfig();
        if (config.player == null) config.player = new PlayerConfig();
        if (config.player.explosiveBowConfig == null) config.player.explosiveBowConfig = new ExplosiveBowConfig();
        if (config.player.bowWhitelistConfig == null) config.player.bowWhitelistConfig = new BowWhitelistConfig();

        // Validiere Companion-Konfiguration
        if (config.companion.maxCompanions < 0 || config.companion.maxCompanions > 100) {
            GodHand.LOGGER.warn("Invalid maxCompanions value: {}, setting to 1", config.companion.maxCompanions);
            config.companion.maxCompanions = 1;
        }
        if (config.companion.followDistance <= 0) {
            GodHand.LOGGER.warn("Invalid followDistance value: {}, setting to 3.0", config.companion.followDistance);
            config.companion.followDistance = 3.0;
        }
        if (config.companion.defendRadius <= 0) {
            GodHand.LOGGER.warn("Invalid defendRadius value: {}, setting to 10.0", config.companion.defendRadius);
            config.companion.defendRadius = 10.0;
        }
        if (config.companion.recruitRadius <= 0) {
            GodHand.LOGGER.warn("Invalid recruitRadius value: {}, setting to 10.0", config.companion.recruitRadius);
            config.companion.recruitRadius = 10.0;
        }
        if (config.companion.extraHealthAmount < 0 || config.companion.extraHealthAmount > 1000) {
            GodHand.LOGGER.warn("Invalid extraHealthAmount value: {}, setting to 100", config.companion.extraHealthAmount);
            config.companion.extraHealthAmount = 100;
        }

        // Validiere Player-Konfiguration
        if (config.player.arrowDuplicationAmount < 0 || config.player.arrowDuplicationAmount > 100) {
            GodHand.LOGGER.warn("Invalid arrowDuplicationAmount value: {}, setting to 5", config.player.arrowDuplicationAmount);
            config.player.arrowDuplicationAmount = 5;
        }
        if (config.player.arrowSeekRadius <= 0 || config.player.arrowSeekRadius > 100.0) {
            GodHand.LOGGER.warn("Invalid arrowSeekRadius value: {}, setting to 20.0", config.player.arrowSeekRadius);
            config.player.arrowSeekRadius = 20.0;
        }

        // Validiere Explosive Bow Konfiguration
        if (config.player.explosiveBowConfig.explosionRadius <= 0 || config.player.explosiveBowConfig.explosionRadius > 50.0) {
            GodHand.LOGGER.warn("Invalid explosionRadius value: {}, setting to 3.0", config.player.explosiveBowConfig.explosionRadius);
            config.player.explosiveBowConfig.explosionRadius = 3.0;
        }
        if (config.player.explosiveBowConfig.explosionMode < 0 || config.player.explosiveBowConfig.explosionMode > 1) {
            GodHand.LOGGER.warn("Invalid explosionMode value: {}, setting to 0", config.player.explosiveBowConfig.explosionMode);
            config.player.explosiveBowConfig.explosionMode = 0;
        }

        // Sicherstellen, dass die Whitelist nicht null ist und eine thread-sichere Implementierung verwendet
        if (config.player.bowWhitelistConfig.whitelistedPlayers == null) {
            config.player.bowWhitelistConfig.whitelistedPlayers = ConcurrentHashMap.newKeySet();
        } else if (!(config.player.bowWhitelistConfig.whitelistedPlayers instanceof ConcurrentHashMap.KeySetView)) {
            Set<String> newSet = ConcurrentHashMap.newKeySet();
            newSet.addAll(config.player.bowWhitelistConfig.whitelistedPlayers);
            config.player.bowWhitelistConfig.whitelistedPlayers = newSet;
        }
    }

    /**
     * Speichert die aktuelle Konfiguration in die Konfigurationsdatei.
     * @param config Die zu speichernde GodHandConfig-Instanz.
     */
    public static void save(GodHandConfig config) {
        validateAndCorrectConfig(config);
        String json;
        synchronized (config) {
            json = GSON.toJson(config);
        }

        try (FileWriter writer = new FileWriter(CONFIG_PATH.toFile())) {
            writer.write(json);
        } catch (IOException e) {
            GodHand.LOGGER.error("Failed to save config.", e);
        }
    }

    /**
     * Speichert die aktuelle Konfiguration asynchron in die Konfigurationsdatei.
     * @param config Die zu speichernde GodHandConfig-Instanz.
     */
    public static void saveAsync(GodHandConfig config) {
        validateAndCorrectConfig(config);
        // Die Serialisierung erfolgt hier im aufrufenden Thread, um einen konsistenten Zustand
        // der Konfiguration einzufangen, bevor weitere Änderungen vorgenommen werden können.
        // Dank ConcurrentHashMap.newKeySet() ist whitelistedPlayers während GSON's Iteration sicher.
        String json;
        synchronized (config) {
            json = GSON.toJson(config);
        }

        SAVE_EXECUTOR.submit(() -> {
            try (FileWriter writer = new FileWriter(CONFIG_PATH.toFile())) {
                writer.write(json);
            } catch (IOException e) {
                GodHand.LOGGER.error("Failed to save config asynchronously.", e);
            }
        });
    }
}

package com.yourcompany.godhand;


import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.damage.DamageSource;
import net.minecraft.entity.damage.DamageTypes;
import net.minecraft.entity.effect.StatusEffectInstance;
import net.minecraft.entity.effect.StatusEffects;

import net.minecraft.text.Text;
import net.minecraft.entity.mob.PathAwareEntity;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Verwaltet die Kernfunktionen der GodHand Mod, wie God Mode und Flugmodus.
 */
public class GodHandFeatures {
    /**
     * Default constructor for GodHandFeatures.
     */
    public GodHandFeatures() {
        super();
    }


    /** Speichert die UUIDs von Spielern und den Zeitpunkt, zu dem ihr Flugmodus deaktiviert wurde, um eine kurze Fallschaden-Gnadenfrist zu gewähren. */
    private static final Map<UUID, Long> RECENTLY_DISABLED_FLIGHT = new ConcurrentHashMap<>();

    /**
     * Überprüft, ob der God Mode für die gegebene Entität aktiviert ist.
     * @param entity Die Entität, für die der God Mode überprüft werden soll.
     * @return True, wenn der God Mode für die Entität aktiviert ist, sonst false.
     */
    public static boolean isGodModeEnabled(LivingEntity entity) {
        if (GodHandConfig.getInstance().godMode.enabled) {
            PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
            if (player == null) { return false; }
            return entity.getUuid().equals(player.getUuid());
        }
        return false;
    }

    /**
     * Behandelt eingehenden Schaden für eine Entität basierend auf den God Mode-Einstellungen.
     * @param entity Die Entität, die Schaden erleidet.
     * @param source Die Schadensquelle.
     * @param amount Die Höhe des Schadens.
     * @return True, wenn der Schaden angewendet werden soll, false, wenn er abgebrochen werden soll.
     */
    public static boolean handleDamage(LivingEntity entity, DamageSource source, float amount) {
        // Friendly Fire Prevention (Companions) - Independent of player checks!
        if (source.getAttacker() instanceof net.minecraft.entity.player.PlayerEntity attackerPlayer && entity instanceof PathAwareEntity targetEntity) {
            if (CompanionManager.isCompanion(targetEntity) && java.util.Objects.equals(attackerPlayer.getUuid(), CompanionManager.getOwnerUuid(targetEntity))) {
                DiagnosticManager.log("handleDamage: Friendly Fire detected, blocking damage to companion.");
                return false; // Schaden an eigenen Begleitern blockieren
            }
        }

        // Nur God Mode und Player Features auf Spieler anwenden
        if (!(entity instanceof net.minecraft.entity.player.PlayerEntity player)) {
            return true; // Schaden für Nicht-Spieler zulassen
        }

        GodHandConfig.GodModeConfig config = GodHandConfig.getInstance().godMode;

        // Fallschaden-Gnadenfrist für Spieler
        if (source.isOf(DamageTypes.FALL)) {
            Long disabledTime = RECENTLY_DISABLED_FLIGHT.get(player.getUuid());
            if (disabledTime != null) {
                if (System.currentTimeMillis() - disabledTime < 5000) { // 5 Sekunden Gnadenfrist
                    DiagnosticManager.log("handleDamage: Fallschaden-Gnadenfrist aktiv, Schaden blockiert.");
                    return false; // Fallschaden abbrechen
                } else {
                    RECENTLY_DISABLED_FLIGHT.remove(player.getUuid()); // Alten Eintrag bereinigen
                }
            }
        }

        // Priorität 1: God Mode
        if (config.enabled) {
            if (source.isOf(DamageTypes.OUT_OF_WORLD)) {
                DiagnosticManager.log("handleDamage: God Mode ist aktiviert, aber Schaden ist OUT_OF_WORLD, Schaden zugelassen.");
                return true; // OUT_OF_WORLD Schaden im God Mode zulassen
            }
            DiagnosticManager.log("handleDamage: God Mode ist aktiviert, blockiere allen Schaden.");
            return false; // Allen anderen Schaden im God Mode blockieren
        }

        // Priorität 2: Smart Mode (wird nur ausgeführt, wenn God Mode deaktiviert ist)
        if (config.smartModeEnabled) {
            // Prüfe, ob der Schaden den Spieler töten würde
            if (player.getHealth() - amount <= 0.0F) {
                // Simuliere den Totem-Effekt
                player.setHealth(1.0F); // Setze Gesundheit auf 1.0 (ein halbes Herz)
                player.addStatusEffect(new StatusEffectInstance(StatusEffects.REGENERATION, 900, 1)); // Regeneration II für 45 Sekunden
                player.addStatusEffect(new StatusEffectInstance(StatusEffects.FIRE_RESISTANCE, 800, 0)); // Feuerresistenz für 40 Sekunden
                player.addStatusEffect(new StatusEffectInstance(StatusEffects.ABSORPTION, 100, 1)); // Absorption II für 5 Sekunden

                // Wir senden eine Nachricht sicher über die Basisklasse
                player.sendMessage(Text.translatable("godhand.chat.smartmode.totem_simulated"), false);

                DiagnosticManager.log("handleDamage: Smart Mode - Totem-Effekt simuliert. Schaden blockiert.");
                return false; // Schaden blockieren
            }
            // Wenn der Schaden nicht tödlich ist, erlaube ihn.
            DiagnosticManager.log("handleDamage: Smart Mode ist aktiviert, nicht-tödlicher Schaden zugelassen.");
            return true;
        }

        return true; // Standardmäßig Schaden zulassen, wenn keine der obigen Bedingungen zutrifft
    }

    /**
     * Schaltet den God Mode für den Spieler um.
     */
    public static void toggleGodMode() {
        GodHandConfig config = GodHandConfig.getInstance();
        boolean wasSmartModeEnabled = config.godMode.smartModeEnabled;
        config.godMode.enabled = !config.godMode.enabled;

        // Wenn God Mode aktiviert wird, deaktiviere den Smart Mode
        if (config.godMode.enabled && wasSmartModeEnabled) {
            config.godMode.smartModeEnabled = false;
            DiagnosticManager.log("Smart Mode was disabled because God Mode was enabled.");
        }

        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("God Mode toggled to: " + config.godMode.enabled);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        boolean enabled = config.godMode.enabled;
        player.sendMessage(Text.translatable("text.godhand.chat.godmode.updated", enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);
        if (config.godMode.enabled && wasSmartModeEnabled) {
            player.sendMessage(Text.translatable("godhand.chat.smartmode.disabled_by_god_mode"), false);
        }
    }

    /**
     * Schaltet die Unverwundbarkeit nach dem Respawn um.
     */
    public static void toggleRespawnInvulnerability() {
        GodHandConfig config = GodHandConfig.getInstance();
        config.godMode.respawnInvulnerability = !config.godMode.respawnInvulnerability;
        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("Respawn Invulnerability toggled to: " + config.godMode.respawnInvulnerability);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        player.sendMessage(Text.translatable("text.godhand.chat.respawn_invulnerability.updated", config.godMode.respawnInvulnerability ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);
    }

    /**
     * Schaltet das Blockieren von Explosionen um.
     */
    public static void toggleBlockExplosions() {
        GodHandConfig config = GodHandConfig.getInstance();
        config.godMode.blockExplosions = !config.godMode.blockExplosions;
        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("Block Explosions toggled to: " + config.godMode.blockExplosions);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        player.sendMessage(Text.translatable("text.godhand.chat.block_explosions.updated", config.godMode.blockExplosions ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);
    }

    /**
     * Schaltet das Blockieren von Feuerschaden um.
     */
    public static void toggleBlockFire() {
        GodHandConfig config = GodHandConfig.getInstance();
        config.godMode.blockFire = !config.godMode.blockFire;
        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("Block Fire toggled to: " + config.godMode.blockFire);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        player.sendMessage(Text.translatable("text.godhand.chat.block_fire.updated", config.godMode.blockFire ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);
    }

    /**
     * Schaltet den Smart Mode um.
     */
    public static void toggleSmartMode() {
        GodHandConfig config = GodHandConfig.getInstance();
        config.godMode.smartModeEnabled = !config.godMode.smartModeEnabled;
        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("Smart Mode toggled to: " + config.godMode.smartModeEnabled);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        player.sendMessage(Text.translatable("text.godhand.chat.smart_mode.updated", config.godMode.smartModeEnabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);
    }

    /**
     * Schaltet den Diagnostic Mode um.
     */
    public static void toggleDiagnosticMode() {
        GodHandConfig config = GodHandConfig.getInstance();
        config.godMode.diagnosticModeEnabled = !config.godMode.diagnosticModeEnabled;
        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("Diagnostic Mode toggled to: " + config.godMode.diagnosticModeEnabled);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        player.sendMessage(Text.translatable("text.godhand.chat.diagnostic_mode.updated", config.godMode.diagnosticModeEnabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);
    }

    /**
     * Schaltet den Flugmodus für den Spieler um.
     */
    public static void toggleFlight() {
        GodHandConfig config = GodHandConfig.getInstance();
        config.godMode.flightEnabled = !config.godMode.flightEnabled;
        GodHandConfig.saveAsync(config);
        DiagnosticManager.log("Flight toggled to: " + config.godMode.flightEnabled);
        PlayerEntity player = net.minecraft.client.MinecraftClient.getInstance().player;
        if (player == null) { return; }
        boolean enabled = config.godMode.flightEnabled;
        player.getAbilities().allowFlying = enabled;
        if (!enabled) {
            player.getAbilities().flying = false;
            RECENTLY_DISABLED_FLIGHT.put(player.getUuid(), System.currentTimeMillis());
        }
        player.sendAbilitiesUpdate();
        player.sendMessage(Text.translatable("text.godhand.chat.flight.updated", enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off")), false);

        // Diagnostic Check
        if (player.getAbilities().allowFlying == enabled) {
            DiagnosticManager.log(DiagnosticManager.LogLevel.INFO, "Flight ability is correctly set to " + enabled + ".");
        } else {
            DiagnosticManager.log(DiagnosticManager.LogLevel.WARN, "Flight ability not correctly set after toggle.");
        }
    }

    /**
     * Wendet die God Mode-Effekte auf den Spieler an (Leben, Hunger, Flug).
     * @param player Der Spieler, auf den die Effekte angewendet werden sollen.
     */
    public static void applyGodModeEffects(PlayerEntity player) {
        GodHandConfig.GodModeConfig config = GodHandConfig.getInstance().godMode;

        // Main God Mode: Absolute Unverwundbarkeit und volle Stats
        if (config.enabled) {
            player.setHealth(player.getMaxHealth());
            player.getHungerManager().setFoodLevel(20);
            player.getHungerManager().setSaturationLevel(20.0F);
            DiagnosticManager.log("applyGodModeEffects: God Mode - Player stats maxed.");
        }
        // Smart Mode: Regeneration und Speed-Boost (nur wenn God Mode aus ist)
        else if (config.smartModeEnabled) {
            // Regeneration
            if (player.getHealth() < player.getMaxHealth()) {
                player.heal(1.0F); // Heilt ein halbes Herz pro Tick
            }
            // Speed-Boost
            player.addStatusEffect(new StatusEffectInstance(StatusEffects.SPEED, 2, 0, true, false)); // Speed I, kurz, um dauerhaft zu sein
            DiagnosticManager.log("applyGodModeEffects: Smart Mode - Applied regeneration and speed boost.");
        }


        // Apply flight abilities based on config.flightEnabled, independent of main God Mode
        player.getAbilities().allowFlying = config.flightEnabled;
        if (!config.flightEnabled && player.getAbilities().flying) {
            player.getAbilities().flying = false;
            RECENTLY_DISABLED_FLIGHT.put(player.getUuid(), System.currentTimeMillis());
        }
        player.sendAbilitiesUpdate();
        DiagnosticManager.log("applyGodModeEffects: Player flight abilities updated. allowFlying=" + config.flightEnabled);
    }
}

