import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.text.Text;

/**
 * Ein benutzerdefinierter Absturzbildschirm für die GodHand Mod, der bei unbehandelten Ausnahmen angezeigt wird.
 */
public class GodHandCrashScreen extends Screen {
 // Nicht mehr final
    private final String errorMessage;
    private final boolean canContinue;

    /**
     * Erstellt einen neuen GodHandCrashScreen mit einer gegebenen Ursache.
     * @param cause Die Ursache des Absturzes.
     */
    public GodHandCrashScreen(Throwable cause) {
        this(cause, Text.translatable("godhand.crashscreen.title"), false);
    }

    /**
     * Erstellt einen neuen GodHandCrashScreen mit einer gegebenen Ursache, einem Titel und der Option, ob das Spiel fortgesetzt werden kann.
     * @param cause Die Ursache des Absturzes.
     * @param title Der Titel des Absturzbildschirms.
     * @param canContinue Gibt an, ob das Spiel nach dem Absturz fortgesetzt werden kann.
     */
    public GodHandCrashScreen(Throwable cause, Text title, boolean canContinue) {
        super(title);
        this.errorMessage = cause.getMessage() != null ? cause.getMessage() : cause.getClass().getSimpleName();
        this.canContinue = canContinue;

        GodHand.LOGGER.error("GodHand Mod crashed!", cause);
    }

    @Override
    protected void init() {
        super.init();
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("godhand.crashscreen.exit"), (button) -> {
            this.client.scheduleStop();
        }).dimensions(this.width / 2 - 100, this.height - 40, 200, 20).build());

        if (canContinue) {
            this.addDrawableChild(ButtonWidget.builder(Text.translatable("godhand.crashscreen.continue"), (button) -> {
                this.client.setScreen(null);
                this.client.mouse.lockCursor();
            }).dimensions(this.width / 2 - 100, this.height - 65, 200, 20).build());
        }
    }

    @Override
    public void render(net.minecraft.client.gui.DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 20, 0xFFFFFF);
        context.drawCenteredTextWithShadow(this.textRenderer, Text.translatable("godhand.crashscreen.message", errorMessage), this.width / 2, 40, 0xFF0000);

        super.render(context, mouseX, mouseY, delta);
    }

    @Override
    public boolean shouldPause() {
        return true;
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.GodHandConfig;
import com.yourcompany.godhand.network.ToggleMagicBowPacket;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.gui.widget.SliderWidget;
import net.minecraft.text.Text;

/**
 * Konfigurationsbildschirm für den Magischen Bogen.
 */
public class MagicArrowSettingsScreen extends Screen {

    private final Screen parent;
    private SliderWidget searchRadiusSlider;
    private SliderWidget megaSpeedSlider;
    private ButtonWidget toggleButton;

    /**
     * Konstruktor.
     * @param parent Der uebergeordnete Bildschirm.
     */
    public MagicArrowSettingsScreen(Screen parent) {
        super(Text.translatable("text.godhand.magic_arrow.title", "Magic Arrow Settings"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        super.init();

        int buttonWidth = 200;
        int buttonHeight = 20;
        int buttonSpacing = 8;
        int numberOfButtons = 4;
        int totalHeight = (buttonHeight * numberOfButtons) + (buttonSpacing * (numberOfButtons - 1));

        int startY = Math.max(30, this.height / 2 - totalHeight / 2);
        int x = this.width / 2 - buttonWidth / 2;

        GodHandConfig config = GodHandConfig.getInstance();

        // Magic Bow Toggle
        this.toggleButton = ButtonWidget.builder(
            Text.translatable("text.godhand.player.magic_bow.status_combined", getStatusText(config.player.magicBowEnabled)),
            (button) -> {
                config.player.magicBowEnabled = !config.player.magicBowEnabled;
                if (config.player.magicBowEnabled) {
                    config.player.superBowEnabled = false; // Disable Super Bow
                }
                GodHandConfig.saveAsync(config);
                net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new com.yourcompany.godhand.network.ToggleMagicBowPacket());
                button.setMessage(Text.translatable("text.godhand.player.magic_bow.status_combined", getStatusText(config.player.magicBowEnabled)));
                updateSliderStates();
            }
        ).dimensions(x, startY, buttonWidth, buttonHeight).build();
        this.addDrawableChild(this.toggleButton);

        // Search Radius Slider
        this.searchRadiusSlider = new SliderWidget(x, startY + (buttonHeight + buttonSpacing), buttonWidth, buttonHeight,
                Text.translatable("text.godhand.player_settings.seek_radius", String.format("%.1f", config.player.arrowSeekRadius)),
                (config.player.arrowSeekRadius - 5.0) / 95.0) {
            @Override
            protected void updateMessage() {
                this.setMessage(Text.translatable("text.godhand.player_settings.seek_radius", String.format("%.1f", getValue())));
            }

            @Override
            protected void applyValue() {
                config.player.arrowSeekRadius = getValue();
                GodHandConfig.saveAsync(config);
            }

            private double getValue() {
                return (this.value * 95.0) + 5.0;
            }
        };
        this.addDrawableChild(this.searchRadiusSlider);

        // Mega Speed Multiplier Slider
        this.megaSpeedSlider = new SliderWidget(x, startY + (buttonHeight + buttonSpacing) * 2, buttonWidth, buttonHeight,
                Text.translatable("text.godhand.magic_arrow.mega_speed", "Mega Speed: 1.0x"),
                0.1) {
            @Override
            protected void updateMessage() {
                this.setMessage(Text.translatable("text.godhand.magic_arrow.mega_speed", "Mega Speed: " + String.format("%.1fx", this.value * 10 + 1)));
            }

            @Override
            protected void applyValue() {
                // Future Implementation: Sync to Config
            }
        };
        this.addDrawableChild(this.megaSpeedSlider);

        // Back Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 3, buttonWidth, buttonHeight)
        .build());

        updateSliderStates();
    }

    private void updateSliderStates() {
        GodHandConfig config = GodHandConfig.getInstance();
        this.searchRadiusSlider.active = config.player.magicBowEnabled;
        this.megaSpeedSlider.active = config.player.magicBowEnabled;
    }

    private Text getStatusText(boolean enabled) {
        return enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
    }

    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        super.render(context, mouseX, mouseY, delta);
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.BowWhitelistManager;
import com.yourcompany.godhand.DiagnosticManager;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.gui.widget.TextFieldWidget;
import net.minecraft.text.Text;
import net.minecraft.util.Formatting;
import com.yourcompany.godhand.GodHand;

import java.util.List;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;

/**
 * Ein Bildschirm zur Verwaltung der Bogen-Whitelist mit verbesserter Fehlerbehandlung und modularer Struktur.
 */
public class SimpleBowWhitelistScreen extends Screen {

    private final Screen parent;
    private TextFieldWidget playerUuidField;
    private ButtonWidget addPlayerButton;
    private ButtonWidget removePlayerButton;
    private List<Text> whitelistedNames;
    private boolean loadingWhitelist = true;
    private String whitelistError = null;

    /**
     * Erstellt einen neuen SimpleBowWhitelistScreen.
     * @param parent Der übergeordnete Bildschirm.
     */
    public SimpleBowWhitelistScreen(Screen parent) {
        super(Text.translatable("godhand.gui.bow_whitelist.title"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        super.init();
        GodHand.LOGGER.info("SimpleBowWhitelistScreen: Initializing screen.");

        // Reset state
        this.loadingWhitelist = true;
        this.whitelistError = null;
        this.whitelistedNames = null;

        int widgetWidth = 200;
        int widgetHeight = 20;
        int x = this.width / 2 - widgetWidth / 2;
        int startY = this.height / 2 - (widgetHeight * 3) - 10;

        // Player UUID/Name Field
        playerUuidField = new TextFieldWidget(this.textRenderer, x, startY, widgetWidth, widgetHeight, Text.translatable("godhand.gui.bow_whitelist.player_field"));
        playerUuidField.setMaxLength(36); // UUID length
        this.addDrawableChild(playerUuidField);

        // Add Player Button
        addPlayerButton = ButtonWidget.builder(
            Text.translatable("godhand.gui.bow_whitelist.add_player"),
            (button) -> {
                handleAddPlayer();
            }
        ).dimensions(x, startY + widgetHeight + 5, widgetWidth / 2 - 2, widgetHeight).build();
        this.addDrawableChild(addPlayerButton);

        // Remove Player Button
        removePlayerButton = ButtonWidget.builder(
            Text.translatable("godhand.gui.bow_whitelist.remove_player"),
            (button) -> {
                handleRemovePlayer();
            }
        ).dimensions(x + widgetWidth / 2 + 2, startY + widgetHeight + 5, widgetWidth / 2 - 2, widgetHeight).build();
        this.addDrawableChild(removePlayerButton);

        // Back Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(this.width / 2 - 100, this.height - 30, 200, 20)
        .build());

        // Load whitelist asynchronously
        loadWhitelistAsync();
    }

    private void handleAddPlayer() {
        String input = playerUuidField.getText().trim();
        GodHand.LOGGER.info("SimpleBowWhitelistScreen: Add Player button clicked with input: " + input);
        if (!input.isEmpty()) {
            net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new com.yourcompany.godhand.network.UpdateBowWhitelistPacket(input, true));
            this.client.player.sendMessage(Text.translatable("godhand.chat.bow_whitelist.update_requested", input).formatted(Formatting.YELLOW), false);
            playerUuidField.setText("");
            // Refresh will happen via Sync packet from server
            loadWhitelistAsync();
        } else {
            GodHand.LOGGER.warn("SimpleBowWhitelistScreen: Add Player button clicked with empty input.");
        }
    }

    private void handleRemovePlayer() {
        String input = playerUuidField.getText().trim();
        GodHand.LOGGER.info("SimpleBowWhitelistScreen: Remove Player button clicked with input: " + input);
        if (!input.isEmpty()) {
            net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new com.yourcompany.godhand.network.UpdateBowWhitelistPacket(input, false));
            this.client.player.sendMessage(Text.translatable("godhand.chat.bow_whitelist.update_requested", input).formatted(Formatting.YELLOW), false);
            playerUuidField.setText("");
            // Refresh will happen via Sync packet from server
            loadWhitelistAsync();
        } else {
            GodHand.LOGGER.warn("SimpleBowWhitelistScreen: Remove Player button clicked with empty input.");
        }
    }

    private void loadWhitelistAsync() {
        this.loadingWhitelist = true;
        CompletableFuture.supplyAsync(() -> {
            try {
                return BowWhitelistManager.getWhitelistedPlayerNames(this.client.getServer());
            } catch (Exception e) {
                GodHand.LOGGER.error("SimpleBowWhitelistScreen: Failed to load whitelist", e);
                DiagnosticManager.log(DiagnosticManager.LogLevel.CRITICAL, "Failed to load bow whitelist - " + e.getMessage());
                throw e;
            }
        }).thenAccept(names -> {
            this.whitelistedNames = names;
            this.loadingWhitelist = false;
            this.whitelistError = null;
            GodHand.LOGGER.debug("SimpleBowWhitelistScreen: Whitelist loaded successfully. Count: " + names.size());
        }).exceptionally(throwable -> {
            this.loadingWhitelist = false;
            this.whitelistError = "Failed to load whitelist: " + throwable.getMessage();
            GodHand.LOGGER.error("SimpleBowWhitelistScreen: Exception while loading whitelist", throwable);
            return null;
        });
    }

    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        GodHand.LOGGER.debug("SimpleBowWhitelistScreen: Rendering screen.");

        // Display Whitelisted Players
        int currentY = this.height / 2 - (this.textRenderer.fontHeight * 5 / 2) + (this.height / 2 - (20 * 3) - 10) + (20 + 5) * 2 + 10;

        if (this.loadingWhitelist) {
            context.drawCenteredTextWithShadow(this.textRenderer, Text.translatable("text.godhand.loading"), this.width / 2, currentY, 0xFFFFFF);
        } else if (this.whitelistError != null) {
            context.drawCenteredTextWithShadow(this.textRenderer, Text.translatable("text.godhand.error", this.whitelistError), this.width / 2, currentY, 0xFF5555);
        } else if (this.whitelistedNames != null) {
            if (this.whitelistedNames.isEmpty()) {
                context.drawCenteredTextWithShadow(this.textRenderer, Text.translatable("godhand.gui.bow_whitelist.no_players"), this.width / 2, currentY, 0xFFFFFF);
                GodHand.LOGGER.debug("SimpleBowWhitelistScreen: No whitelisted players to display.");
            } else {
                context.drawCenteredTextWithShadow(this.textRenderer, Text.translatable("godhand.gui.bow_whitelist.current_players"), this.width / 2, currentY, 0xFFFFFF);
                currentY += this.textRenderer.fontHeight + 5;
                for (Text name : this.whitelistedNames) {
                    context.drawCenteredTextWithShadow(this.textRenderer, name, this.width / 2, currentY, 0xFFFFFF);
                    currentY += this.textRenderer.fontHeight + 2;
                    GodHand.LOGGER.debug("SimpleBowWhitelistScreen: Displaying whitelisted player: " + name.getString());
                }
            }
        }

        super.render(context, mouseX, mouseY, delta);
    }

    @Override
    public boolean shouldPause() {
        return false;
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.CompanionManager;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;
import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import com.yourcompany.godhand.network.ToggleMagicBowPacket;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.text.Text;
import net.minecraft.entity.player.PlayerEntity;
import com.yourcompany.godhand.GodHand;

/**
 * Screen.
 */
public class SimpleCompanionScreen extends Screen {

    private final Screen parent;

    /**
     * Bool.
     */
    public static boolean serverConfirmedHasCompanions = false;
    /**
     * Bool.
     */
    public static boolean waitingForServerResponse = true;
    private boolean statusRequested = false;

    private ButtonWidget releaseButton;
    private ButtonWidget manageButton;
    private ButtonWidget effectsButton;

    /**
     * Init.
     * @param parent Parent screen.
     */
    public SimpleCompanionScreen(Screen parent) {
        super(Text.translatable("text.godhand.companion.title"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        super.init();

        if (!statusRequested) {
            waitingForServerResponse = true;
            statusRequested = true;
            net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new ToggleMagicBowPacket());
        }

        int buttonWidth = Math.min(200, this.width / 3);
        int buttonHeight = 20;
        int buttonSpacing = 8;
        int startY = Math.max(40, this.height / 2 - (buttonHeight * 3) - 20);
        int x = this.width / 2 - buttonWidth / 2;

        int totalHeight = (buttonHeight * 5) + (buttonSpacing * 4) + 20;
        if (startY + totalHeight > this.height - 40) {
            startY = this.height - totalHeight - 40;
        }

        PlayerEntity player = this.client.player;
        boolean buttonsActive = serverConfirmedHasCompanions && !waitingForServerResponse;

        ButtonWidget recruitButton = ButtonWidget.builder(Text.translatable("text.godhand.companion.recruit"), (button) -> {
            if (player != null) {
                CompanionManager.recruitNearestCompanion(player);
                waitingForServerResponse = true;
                net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new ToggleMagicBowPacket());
            }
        })
        .dimensions(x, startY, buttonWidth, buttonHeight)
        .build();
        this.addDrawableChild(recruitButton);

        releaseButton = ButtonWidget.builder(Text.translatable("text.godhand.companion.release"), (button) -> {
            if (player != null) {
                net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new ToggleMagicBowPacket());
                waitingForServerResponse = true;
                net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new ToggleMagicBowPacket());
            }
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing), buttonWidth, buttonHeight)
        .build();
        releaseButton.active = buttonsActive;
        this.addDrawableChild(releaseButton);

        manageButton = ButtonWidget.builder(Text.translatable("text.godhand.companion.manage"), (button) -> {
            this.client.setScreen(new CompanionManagementScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 2, buttonWidth, buttonHeight)
        .build();
        manageButton.active = buttonsActive;
        this.addDrawableChild(manageButton);

        effectsButton = ButtonWidget.builder(Text.translatable("text.godhand.companion.effects"), (button) -> {
            this.client.setScreen(new CompanionEffectsScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 3, buttonWidth, buttonHeight)
        .build();
        effectsButton.active = buttonsActive;
        this.addDrawableChild(effectsButton);

        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(this.width / 2 - 100, this.height - 30, 200, 20)
        .build());
    }

    @Override
    public void tick() {
        super.tick();
        boolean buttonsActive = serverConfirmedHasCompanions && !waitingForServerResponse;
        if (releaseButton != null) releaseButton.active = buttonsActive;
        if (manageButton != null) manageButton.active = buttonsActive;
        if (effectsButton != null) effectsButton.active = buttonsActive;
    }

    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        super.render(context, mouseX, mouseY, delta);
    }

    @Override
    public boolean shouldPause() {
        return false;
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.CompanionManager;
import com.yourcompany.godhand.GodHandConfig;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.gui.widget.SliderWidget;
import net.minecraft.text.Text;

/**
 * Ein Bildschirm zur Konfiguration der Begleiter-Einstellungen.
 */
public class SimpleCompanionSettingsScreen extends Screen {

    private final Screen parent;
    private SliderWidget maxCompanionsSlider;
    private SliderWidget followDistanceSlider;
    private SliderWidget defendRadiusSlider;

    /**
     * Erstellt einen neuen SimpleCompanionSettingsScreen.
     * @param parent Der übergeordnete Bildschirm, zu dem man zurückkehren kann.
     */
    public SimpleCompanionSettingsScreen(Screen parent) {
        super(Text.translatable("text.godhand.companion.title"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        super.init();

        int buttonWidth = 200;
        int buttonHeight = 20;
        int x = this.width / 2 - buttonWidth / 2;
        int y = this.height / 2 - (buttonHeight * 2) - 10;

        // Max Companions Slider
        GodHandConfig config = GodHandConfig.getInstance();
        this.maxCompanionsSlider = new SliderWidget(x, y, buttonWidth, buttonHeight, 
                Text.translatable("text.godhand.companion.max_companions", config.companion.maxCompanions),
                (config.companion.maxCompanions - 1) / 99.0) {
            @Override
            protected void updateMessage() {
                this.setMessage(Text.translatable("text.godhand.companion.max_companions", (int) (this.value * 99) + 1));
            }

            @Override
            protected void applyValue() {
                int newValue = (int) (this.value * 99) + 1;
                GodHandConfig.getInstance().companion.maxCompanions = newValue;
                GodHandConfig.saveAsync(GodHandConfig.getInstance());
                client.player.sendMessage(Text.translatable("godhand.chat.companion_settings.max_companions_updated", newValue), false);
                CompanionManager.updateAllCompanionGoals(client.player);
            }
        };
        this.addDrawableChild(this.maxCompanionsSlider);

        // Follow Distance Slider
        this.followDistanceSlider = new SliderWidget(x, y + buttonHeight + 5, buttonWidth, buttonHeight, 
                Text.translatable("text.godhand.companion.follow_distance", String.format("%.1f", config.companion.followDistance)),
                (config.companion.followDistance - 1.0) / 127.0) {
            @Override
            protected void updateMessage() {
                double value = (this.value * 127.0) + 1.0;
                if (value > 127) {
                    this.setMessage(Text.translatable("text.godhand.companion.follow_distance.infinite"));
                } else {
                    this.setMessage(Text.translatable("text.godhand.companion.follow_distance", String.format("%.1f", value)));
                }
            }

            @Override
            protected void applyValue() {
                double newValue = (this.value * 127.0) + 1.0;
                GodHandConfig.getInstance().companion.followDistance = newValue;
                GodHandConfig.saveAsync(GodHandConfig.getInstance());
                if (newValue > 127) {
                    client.player.sendMessage(Text.translatable("godhand.chat.companion_settings.follow_distance_updated.infinite"), false);
                } else {
                    client.player.sendMessage(Text.translatable("godhand.chat.companion_settings.follow_distance_updated", String.format("%.1f", newValue)), false);
                }
                CompanionManager.updateAllCompanionGoals(client.player);
            }
        };
        this.addDrawableChild(this.followDistanceSlider);

        // Defend Radius Slider
        this.defendRadiusSlider = new SliderWidget(x, y + (buttonHeight + 5) * 2, buttonWidth, buttonHeight, 
                Text.translatable("text.godhand.companion.defend_radius", String.format("%.1f", config.companion.defendRadius)),
                (config.companion.defendRadius - 5.0) / 25.0) {
            @Override
            protected void updateMessage() {
                this.setMessage(Text.translatable("text.godhand.companion.defend_radius", String.format("%.1f", (this.value * 25) + 5.0)));
            }

            @Override
            protected void applyValue() {
                double newValue = (this.value * 25) + 5.0;
                GodHandConfig.getInstance().companion.defendRadius = newValue;
                GodHandConfig.saveAsync(GodHandConfig.getInstance());
                client.player.sendMessage(Text.translatable("godhand.chat.companion_settings.defend_radius_updated", String.format("%.1f", newValue)), false);
                CompanionManager.updateAllCompanionGoals(client.player);
            }
        };
        this.addDrawableChild(this.defendRadiusSlider);

        // Back Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(this.width / 2 - 100, this.height - 30, 200, 20)
        .build());
    }

    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        super.render(context, mouseX, mouseY, delta);
    }

    @Override
    public boolean shouldPause() {
        return false;
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.GodHandConfig;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.text.Text;

/**
 * Der Hauptbildschirm der GodHand Mod, der Zugriff auf God Mode, Begleiter und Einstellungen bietet.
 */
public class SimpleGodHandScreen extends Screen {

    /**
     * Erstellt einen neuen SimpleGodHandScreen.
     */
    public SimpleGodHandScreen() {
        super(Text.translatable("text.godhand.title"));
    }

    @Override
    protected void init() {
        super.init();

        // Dynamische Button-Größen basierend auf Bildschirmgröße
        int buttonWidth = Math.min(200, this.width / 3);
        int buttonHeight = 20;
        int buttonSpacing = 8;
        int numberOfButtons = 6;
        int totalHeight = (buttonHeight * numberOfButtons) + (buttonSpacing * (numberOfButtons - 1));

        // Intelligent berechneter startY, so dass das gesamte Menü vertikal zentriert wird
        int startY = Math.max(30, this.height / 2 - totalHeight / 2);
        int x = this.width / 2 - buttonWidth / 2;

        // God Mode Button
        this.addDrawableChild(ButtonWidget.builder(getGodModeStatusText(), (button) -> {
            this.client.setScreen(new SimpleGodModeScreen(this));
        })
        .dimensions(x, startY, buttonWidth, buttonHeight)
        .build());

        // Companion Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("text.godhand.companion"), (button) -> {
            this.client.setScreen(new SimpleCompanionScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing), buttonWidth, buttonHeight)
        .build());

        // Player Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("text.godhand.player"), (button) -> {
            this.client.setScreen(new SimplePlayerScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 2, buttonWidth, buttonHeight)
        .build());

        // Settings Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("text.godhand.settings"), (button) -> {
            this.client.setScreen(new SimpleSettingsScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 3, buttonWidth, buttonHeight)
        .build());

        // Magic Bow Settings Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("Magic Bow Settings"), (button) -> {
            this.client.setScreen(new com.yourcompany.godhand.gui.MagicArrowSettingsScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 4, buttonWidth, buttonHeight)
        .build());

        // Close Button - intelligent unten angereiht!
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("godhand.gui.button.close"), (button) -> {
            this.close();
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 5, buttonWidth, buttonHeight)
        .build());
    }

    /**
     * Erstellt den Text für den God Mode Status-Button, der den aktuellen God Mode und Flugmodus anzeigt.
     * @return Der Text für den God Mode Status-Button.
     */
    private Text getGodModeStatusText() {
        boolean godModeEnabled = GodHandConfig.getInstance().godMode.enabled;
        boolean flightEnabled = GodHandConfig.getInstance().godMode.flightEnabled;
        Text godModeStatus = godModeEnabled ? Text.translatable("options.on") : Text.translatable("options.off");
        Text flightStatus = flightEnabled ? Text.translatable("options.on") : Text.translatable("options.off");
