package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.GodHandConfig;
import com.yourcompany.godhand.GodHandFeatures;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.text.Text;

/**
 * Ein Bildschirm zur Konfiguration der God Mode-Einstellungen.
 */
public class SimpleGodModeScreen extends Screen {

    private final Screen parent;

    /**
     * Erstellt einen neuen SimpleGodModeScreen.
     * @param parent Der übergeordnete Bildschirm, zu dem man zurückkehren kann.
     */
    public SimpleGodModeScreen(Screen parent) {
        super(Text.translatable("text.godhand.godmode.title"));
        this.parent = parent;
    }

    /**
     * Überprüft, ob die God Mode-Einstellungen gesperrt sind.
     * @return True, wenn die Einstellungen gesperrt sind, sonst false.
     */
    private boolean areSettingsLocked() {
        return GodHandConfig.getInstance().godMode.godModeSettingsLocked;
    }

    @Override
    protected void init() {
        super.init();

        // Initialisiert die Schaltflächen für die God Mode-Einstellungen.
        int buttonWidth = 200;
        int buttonHeight = 20;
        int x = this.width / 2 - buttonWidth / 2;
        int y = this.height / 2 - (buttonHeight * 3) - 15; // Adjusted startY for the new button

        GodHandConfig.GodModeConfig config = GodHandConfig.getInstance().godMode;

        // --- Settings Lock Button ---
        this.addDrawableChild(ButtonWidget.builder(getLockText(), (button) -> {
            config.godModeSettingsLocked = !config.godModeSettingsLocked;
            GodHandConfig.saveAsync(GodHandConfig.getInstance());
            if (this.client != null && this.client.player != null) {
                this.client.player.sendMessage(config.godModeSettingsLocked ? Text.translatable("godhand.chat.godmode.settings_locked") : Text.translatable("godhand.chat.godmode.settings_unlocked"), false);
            }
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload screen
        })
        .dimensions(x, y, buttonWidth, buttonHeight)
        .build());

        // --- Feature Buttons ---
        boolean settingsLocked = areSettingsLocked();

        int buttonSpacing = buttonHeight + 5;

        // God Mode Status Button
        ButtonWidget godModeButton = ButtonWidget.builder(getGodModeStatusText(), (button) -> {
            GodHandFeatures.toggleGodMode();
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload to update dependent buttons
        })
        .dimensions(x, y + buttonSpacing, buttonWidth, buttonHeight)
        .build();
        godModeButton.active = !settingsLocked;
        this.addDrawableChild(godModeButton);

        // Block Explosions Button
        ButtonWidget blockExplosionsButton = ButtonWidget.builder(getBlockExplosionsText(), (button) -> {
            GodHandFeatures.toggleBlockExplosions();
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload to update button text
        })
        .dimensions(x, y + buttonSpacing * 2, buttonWidth, buttonHeight)
        .build();
        blockExplosionsButton.active = !settingsLocked;
        this.addDrawableChild(blockExplosionsButton);

        // Block Fire Button
        ButtonWidget blockFireButton = ButtonWidget.builder(getBlockFireText(), (button) -> {
            GodHandFeatures.toggleBlockFire();
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload to update button text
        })
        .dimensions(x, y + buttonSpacing * 3, buttonWidth, buttonHeight)
        .build();
        blockFireButton.active = !settingsLocked;
        this.addDrawableChild(blockFireButton);

        // Respawn Invulnerability Button
        ButtonWidget respawnInvulnerabilityButton = ButtonWidget.builder(getRespawnInvulnerabilityText(), (button) -> {
            GodHandFeatures.toggleRespawnInvulnerability();
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload to update button text
        })
        .dimensions(x, y + buttonSpacing * 4, buttonWidth, buttonHeight)
        .build();
        respawnInvulnerabilityButton.active = !settingsLocked;
        this.addDrawableChild(respawnInvulnerabilityButton);

        // Flight Status Button
        ButtonWidget flightButton = ButtonWidget.builder(getFlightStatusText(), (button) -> {
            GodHandFeatures.toggleFlight();
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload to update button text
        })
        .dimensions(x, y + buttonSpacing * 5, buttonWidth, buttonHeight)
        .build();
        flightButton.active = !settingsLocked;
        this.addDrawableChild(flightButton);

        // Smart-Kombat Button
        ButtonWidget smartKombatButton = ButtonWidget.builder(getSmartKombatText(), (button) -> {
            GodHandFeatures.toggleSmartMode();
            this.client.setScreen(new SimpleGodModeScreen(this.parent)); // Reload to update button text
        })
        .dimensions(x, y + buttonSpacing * 6, buttonWidth, buttonHeight)
        .build();
        smartKombatButton.active = !settingsLocked;
        this.addDrawableChild(smartKombatButton);



        // Back Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(this.width / 2 - 100, this.height - 30, 200, 20)
        .build());
    }

    /**
     * Erstellt den Text für den Sperr-Button der God Mode-Einstellungen.
     * @return Der Text für den Sperr-Button.
     */
    private Text getLockText() {
        return areSettingsLocked() ? Text.translatable("godhand.settings.godmode.lock_button.on") : Text.translatable("godhand.settings.godmode.lock_button.off");
    }

    /**
     * Erstellt den Text für den God Mode Status-Button.
     * @return Der Text für den God Mode Status-Button.
     */
    private Text getGodModeStatusText() {
        return Text.translatable("text.godhand.godmode.status", GodHandConfig.getInstance().godMode.enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off"));
    }

    /**
     * Erstellt den Text für den Block Explosions-Button.
     * @return Der Text für den Block Explosions-Button.
     */
    private Text getBlockExplosionsText() {
        boolean enabled = GodHandConfig.getInstance().godMode.blockExplosions;
        Text statusText = enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
        return Text.translatable("text.godhand.godmode.block_explosions.status", statusText);
    }

    /**
     * Erstellt den Text für den Block Fire-Button.
     * @return Der Text für den Block Fire-Button.
     */
    private Text getBlockFireText() {
        boolean enabled = GodHandConfig.getInstance().godMode.blockFire;
        Text statusText = enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
        return Text.translatable("text.godhand.godmode.block_fire.status", statusText);
    }

    /**
     * Erstellt den Text für den Respawn Invulnerability-Button.
     * @return Der Text für den Respawn Invulnerability-Button.
     */
    private Text getRespawnInvulnerabilityText() {
        boolean enabled = GodHandConfig.getInstance().godMode.respawnInvulnerability;
        Text statusText = enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
        return Text.translatable("text.godhand.godmode.respawn_invulnerability.status", statusText);
    }

    /**
     * Erstellt den Text für den Flight Status-Button.
     * @return Der Text für den Flight Status-Button.
     */
    private Text getFlightStatusText() {
        boolean enabled = GodHandConfig.getInstance().godMode.flightEnabled;
        Text statusText = enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
        return Text.translatable("text.godhand.godmode.flight.status_combined", statusText);
    }

    /**
     * Erstellt den Text für den Smart-Kombat-Button.
     * @return Der Text für den Smart-Kombat-Button.
     */
    private Text getSmartKombatText() {
        boolean enabled = GodHandConfig.getInstance().godMode.smartModeEnabled;
        Text statusText = enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
        return Text.translatable("text.godhand.godmode.smart_kombat.status", statusText);
    }

    /**
     * Rendert den Bildschirm.
     */
    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        super.render(context, mouseX, mouseY, delta);

        // Tooltip für Smart-Kombat Button
        for (var child : children()) {
            if (child instanceof ButtonWidget button && button.getMessage().getString().contains(Text.translatable("text.godhand.godmode.smart_kombat").getString())) {
                if (button.isHovered()) {
                    context.drawTooltip(this.textRenderer, Text.translatable("text.godhand.godmode.smart_kombat.tooltip"), mouseX, mouseY);
                }
            }
        }
    }

    /**
     * Gibt an, ob das Spiel pausiert werden soll, wenn dieser Bildschirm geöffnet ist.
     * @return false, da das Spiel nicht pausiert werden soll.
     */
    @Override
    public boolean shouldPause() {
        return false;
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.GodHandConfig;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.text.Text;

/**
 * Ein Bildschirm für spielerbezogene Funktionen wie den Super-Bogen.
 */
public class SimplePlayerScreen extends Screen {

    private final Screen parent;
    private ButtonWidget superBowToggleButton;

    /**
     * Erstellt einen neuen SimplePlayerScreen.
     * @param parent Der übergeordnete Bildschirm.
     */
    public SimplePlayerScreen(Screen parent) {
        super(Text.translatable("text.godhand.player.title"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        super.init();

        int buttonWidth = Math.min(200, this.width / 3);
        int buttonHeight = 20;
        int buttonSpacing = 8;
        int x = this.width / 2 - buttonWidth / 2;
        int startY = Math.max(40, this.height / 2 - (buttonHeight * 2) - 20);

        int totalHeight = (buttonHeight * 3) + (buttonSpacing * 2) + 40;
        if (startY + totalHeight > this.height - 40) {
            startY = this.height - totalHeight - 40;
        }

        GodHandConfig config = GodHandConfig.getInstance();

        // Super Bow Toggle Button
        this.superBowToggleButton = ButtonWidget.builder(
            Text.translatable("text.godhand.player.super_bow.status_combined", getStatusText(config.player.superBowEnabled)),
            (button) -> {
                config.player.superBowEnabled = !config.player.superBowEnabled;
                if (config.player.superBowEnabled) {
                    config.player.magicBowEnabled = false;
                    net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new com.yourcompany.godhand.network.ToggleMagicBowPacket());
                }
                GodHandConfig.saveAsync(config);
                button.setMessage(Text.translatable("text.godhand.player.super_bow.status_combined", getStatusText(config.player.superBowEnabled)));
                this.client.player.sendMessage(Text.translatable("godhand.chat.player.super_bow_updated", getStatusText(config.player.superBowEnabled)), false);
            }
        ).dimensions(x, startY, buttonWidth, buttonHeight).build();
        this.superBowToggleButton.active = !config.player.magicBowEnabled;
        this.addDrawableChild(this.superBowToggleButton);

        // Bow Whitelist Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("godhand.gui.bow_whitelist.button"), (button) -> {
            net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new com.yourcompany.godhand.network.OpenBowWhitelistScreenPacket());
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing), buttonWidth, buttonHeight)
        .build());

        // Player Settings Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("text.godhand.player_settings"), (button) -> {
            this.client.setScreen(new SimplePlayerSettingsScreen(this));
        })
        .dimensions(x, startY + (buttonHeight + buttonSpacing) * 2, buttonWidth, buttonHeight)
        .build());

        // Back Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(this.width / 2 - 100, this.height - 30, 200, 20)
        .build());
    }

    private Text getStatusText(boolean enabled) {
        return enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
    }

    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        super.render(context, mouseX, mouseY, delta);
    }

    @Override
    public boolean shouldPause() {
        return false;
    }
}

package com.yourcompany.godhand.gui;

import com.yourcompany.godhand.GodHandConfig;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.gui.widget.SliderWidget;
import net.minecraft.text.Text;

/**
 * Ein Bildschirm zur Konfiguration der spielerbezogenen Einstellungen, insbesondere für den Super-Bogen.
 */
public class SimplePlayerSettingsScreen extends Screen {

    private final Screen parent;
    private ButtonWidget arrowDuplicationToggle;
    private SliderWidget arrowDuplicationSlider;
    private SliderWidget arrowSeekRadiusSlider;
    private ButtonWidget explosiveBowToggle;
    private ButtonWidget targetAllMobsToggle;
    private SliderWidget explosionRadiusSlider;
    private SliderWidget explosionModeSlider;

    /**
     * Erstellt einen neuen SimplePlayerSettingsScreen.
     * @param parent Der übergeordnete Bildschirm.
     */
    public SimplePlayerSettingsScreen(Screen parent) {
        super(Text.translatable("text.godhand.player_settings.title"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        super.init();

        int widgetWidth = 200;
        int widgetHeight = 20;
        int x = this.width / 2 - widgetWidth / 2;
        int startY = this.height / 2 - (widgetHeight * 4) - 10;

        GodHandConfig config = GodHandConfig.getInstance();

        addArrowDuplicationWidgets(config, x, startY, widgetWidth, widgetHeight);
        addSuperBowWidgets(config, x, startY, widgetWidth, widgetHeight);
        addExplosiveBowWidgets(config, x, startY, widgetWidth, widgetHeight);
        addNavigationWidgets();

        updateArrowDuplicationSliderStates(config.player.arrowDuplicationEnabled);
        updateExplosiveBowSliderStates(config.player.explosiveBowConfig.enabled);
        updateSuperBowSliderStates(config.player.superBowEnabled);
    }

    private void addNavigationWidgets() {
        // Back Button
        this.addDrawableChild(ButtonWidget.builder(Text.translatable("gui.back"), (button) -> {
            this.client.setScreen(this.parent);
        })
        .dimensions(this.width / 2 - 100, this.height - 30, 200, 20)
        .build());
    }

    private void addSuperBowWidgets(GodHandConfig config, int x, int startY, int widgetWidth, int widgetHeight) {
        // Target All Mobs Toggle
        targetAllMobsToggle = ButtonWidget.builder(
            Text.translatable("text.godhand.player_settings.target_all_mobs.status", getStatusText(config.player.superBowTargetsAllMobs)),
            (button) -> {
                config.player.superBowTargetsAllMobs = !config.player.superBowTargetsAllMobs;
                GodHandConfig.saveAsync(config);
                button.setMessage(Text.translatable("text.godhand.player_settings.target_all_mobs.status", getStatusText(config.player.superBowTargetsAllMobs)));
                this.client.player.sendMessage(Text.translatable("godhand.chat.player_settings.target_all_mobs_updated", getStatusText(config.player.superBowTargetsAllMobs)), false);
            }
        ).dimensions(x, startY + (widgetHeight + 5) * 3, widgetWidth, widgetHeight).build();
        this.addDrawableChild(targetAllMobsToggle);
    }

    private void addExplosiveBowWidgets(GodHandConfig config, int x, int startY, int widgetWidth, int widgetHeight) {
        // Explosive Bow Toggle
        explosiveBowToggle = ButtonWidget.builder(
            Text.translatable("godhand.gui.button.explosive_bow", getStatusText(config.player.explosiveBowConfig.enabled)),
            (button) -> {
                config.player.explosiveBowConfig.enabled = !config.player.explosiveBowConfig.enabled;
                GodHandConfig.saveAsync(config);
                button.setMessage(Text.translatable("godhand.gui.button.explosive_bow", getStatusText(config.player.explosiveBowConfig.enabled)));
                updateExplosiveBowSliderStates(config.player.explosiveBowConfig.enabled);
                this.client.player.sendMessage(Text.translatable("godhand.chat.player.explosive_bow_updated", getStatusText(config.player.explosiveBowConfig.enabled)), false);
            }
        ).dimensions(x, startY + (widgetHeight + 5) * 4, widgetWidth, widgetHeight).build();
        this.addDrawableChild(explosiveBowToggle);

        // Explosion Radius Slider
        explosionRadiusSlider = new SliderWidget(x, startY + (widgetHeight + 5) * 5, widgetWidth, widgetHeight,
                Text.translatable("godhand.gui.slider.explosion_radius", String.format("%.1f", config.player.explosiveBowConfig.explosionRadius)),
                config.player.explosiveBowConfig.explosionRadius / 50.0) {
            @Override
            protected void updateMessage() {
                setMessage(Text.translatable("godhand.gui.slider.explosion_radius", String.format("%.1f", getValue())));
            }

            @Override
            protected void applyValue() {
                config.player.explosiveBowConfig.explosionRadius = getValue();
                GodHandConfig.saveAsync(config);
                client.player.sendMessage(Text.translatable("godhand.chat.player.explosion_radius_updated", String.format("%.1f", getValue())), false);
            }

            private double getValue() {
                return this.value * 50.0;
            }
        };
        this.addDrawableChild(explosionRadiusSlider);

        // Explosion Mode Slider
        explosionModeSlider = new SliderWidget(x, startY + (widgetHeight + 5) * 6, widgetWidth, widgetHeight,
                getExplosionModeText(config.player.explosiveBowConfig.explosionMode),
                config.player.explosiveBowConfig.explosionMode / 1.0) {
            @Override
            protected void updateMessage() {
                setMessage(getExplosionModeText(getValue()));
            }

            @Override
            protected void applyValue() {
                config.player.explosiveBowConfig.explosionMode = getValue();
                GodHandConfig.saveAsync(config);
                client.player.sendMessage(Text.translatable("godhand.chat.player.explosion_mode_updated", getExplosionModeText(getValue())), false);
            }

            private int getValue() {
                return (int) Math.round(this.value * 1.0);
            }
        };
        this.addDrawableChild(explosionModeSlider);
    }

    private void addArrowDuplicationWidgets(GodHandConfig config, int x, int startY, int widgetWidth, int widgetHeight) {
        // Arrow Duplication Toggle
        arrowDuplicationToggle = ButtonWidget.builder(
            Text.translatable("text.godhand.player_settings.arrow_duplication.status", getStatusText(config.player.arrowDuplicationEnabled)),
            (button) -> {
                config.player.arrowDuplicationEnabled = !config.player.arrowDuplicationEnabled;
                GodHandConfig.saveAsync(config);
                button.setMessage(Text.translatable("text.godhand.player_settings.arrow_duplication.status", getStatusText(config.player.arrowDuplicationEnabled)));
                updateArrowDuplicationSliderStates(config.player.arrowDuplicationEnabled);
                this.client.player.sendMessage(Text.translatable("godhand.chat.player_settings.arrow_duplication_updated", getStatusText(config.player.arrowDuplicationEnabled)), false);
            }
        ).dimensions(x, startY, widgetWidth, widgetHeight).build();
        this.addDrawableChild(arrowDuplicationToggle);

        // Arrow Duplication Amount Slider
        arrowDuplicationSlider = new SliderWidget(x, startY + widgetHeight + 5, widgetWidth, widgetHeight,
                Text.translatable("text.godhand.player_settings.duplication_amount", config.player.arrowDuplicationAmount),
                (config.player.arrowDuplicationAmount - 1) / 29.0) {
            @Override
            protected void updateMessage() {
                setMessage(Text.translatable("text.godhand.player_settings.duplication_amount", getValue()));
            }

            @Override
            protected void applyValue() {
                config.player.arrowDuplicationAmount = getValue();
                GodHandConfig.saveAsync(config);
                client.player.sendMessage(Text.translatable("godhand.chat.player_settings.duplication_amount_updated", getValue()), false);
            }

            private int getValue() {
                return (int) (this.value * 29) + 1;
            }
        };
        this.addDrawableChild(arrowDuplicationSlider);

        // Arrow Seek Radius Slider
        arrowSeekRadiusSlider = new SliderWidget(x, startY + (widgetHeight + 5) * 2, widgetWidth, widgetHeight,
                Text.translatable("text.godhand.player_settings.seek_radius", String.format("%.1f", config.player.arrowSeekRadius)),
                (config.player.arrowSeekRadius - 5.0) / 95.0) {
            @Override
            protected void updateMessage() {
                setMessage(Text.translatable("text.godhand.player_settings.seek_radius", String.format("%.1f", getValue())));
            }

            @Override
            protected void applyValue() {
                config.player.arrowSeekRadius = getValue();
                GodHandConfig.saveAsync(config);
                client.player.sendMessage(Text.translatable("godhand.chat.player_settings.seek_radius_updated", String.format("%.1f", getValue())), false);
            }

            private double getValue() {
                return (this.value * 95.0) + 5.0;
            }
        };
        this.addDrawableChild(arrowSeekRadiusSlider);
    }

    private void updateSuperBowSliderStates(boolean enabled) {
        // This method will now only update the targetAllMobsToggle based on superBowEnabled
        targetAllMobsToggle.active = enabled;
    }

    private void updateArrowDuplicationSliderStates(boolean enabled) {
        GodHandConfig config = GodHandConfig.getInstance();
        arrowDuplicationSlider.active = enabled && (config.player.superBowEnabled || config.player.magicBowEnabled);
        arrowSeekRadiusSlider.active = enabled && (config.player.superBowEnabled || config.player.magicBowEnabled);
    }

    private void updateExplosiveBowSliderStates(boolean enabled) {
        explosionRadiusSlider.active = enabled;
        explosionModeSlider.active = enabled;
    }

    private Text getStatusText(boolean enabled) {
        return enabled ? Text.translatable("text.godhand.godmode.on") : Text.translatable("text.godhand.godmode.off");
    }

    private Text getExplosionModeText(int mode) {
        return mode == 0 ? Text.translatable("godhand.gui.slider.explosion_mode.damage_only") : Text.translatable("godhand.gui.slider.explosion_mode.destruction");
    }

    @Override
    public void render(DrawContext context, int mouseX, int mouseY, float delta) {
        this.renderBackground(context, mouseX, mouseY, delta);
        context.drawCenteredTextWithShadow(this.textRenderer, this.title, this.width / 2, 15, 0xFFFFFF);
        super.render(context, mouseX, mouseY, delta);
    }

    @Override
    public boolean shouldPause() {
        return false;
    }
}

