        }
    }

    private LivingEntity mockCompanion;
    private NbtCompound mockNbt;
    private CompanionBuffGoal goal;
    private Map<net.minecraft.registry.entry.RegistryEntry<StatusEffect>, StatusEffectInstance> activeEffectsMap;

