        when(mockNormalBlock.getHardness()).thenReturn(1.0F);

        for (int i = 0; i < 15; i++) {
            assertTrue(behavior.canDestroyBlock(null, null, null, mockNormalState, 1.0F), "Should destroy block " + (i + 1));
        }
    }
}

